/* ─────────────────────────────────────────────
 * 6. EDITOR JS
 * ───────────────────────────────────────────── */

function wpconvert_editor_get_js() {
    return <<<'WPCJS'
(function(){
    "use strict";
    if (typeof wpcEditor === "undefined") return;

    var ajax = wpcEditor.ajaxUrl;
    var nonce = wpcEditor.nonce;
    var activeEl = null;
    var toolbar = null;
    var popover = null;
    var originalValue = "";
    var onCancel = null;
    var proTypes = { link:1, section:1, background:1, list:1, video:1 };
    var isPro = wpcEditor.tier === "pro" || wpcEditor.tier === "agency" || wpcEditor.tier === "payg";
    var lastClickX = 0;
    var lastClickY = 0;

    var wpcEditableManifest = [];

    /* EC-EDITOR-025: Register the capture-phase click handler IMMEDIATELY — not
     * inside init() / DOMContentLoaded — so it is the very first capture listener
     * on `document`. Scripts parsed later (anchor-scroll-fix, popup handler,
     * third-party widget JS like Elfsight) will have their listeners queued after
     * this one.  handleClick() only touches document.body (always available by the
     * time a real user click arrives), so no DOM-ready dependency. */
    document.addEventListener("click", function(e) {
        /* EC-FORM-003b: Let unwired booking-form submit buttons reach the browser
         * submit event so the inline safety-net can preventDefault (no reload /
         * map iframe flicker). Without this, freezeScroll() on the button's
         * data-wpc-editable intercept blocks submit entirely in edit mode. */
        var submitCtl = e.target && e.target.closest
            ? e.target.closest('button[type="submit"], input[type="submit"]')
            : null;
        if (submitCtl) {
            var unwiredForm = submitCtl.closest
                ? submitCtl.closest('form[data-wpconvert-form="needs-wiring"]')
                : null;
            if (unwiredForm) return;
        }
        /* EC-EDIT-005: Editor-injected controls and slider navigation must
         * handle their OWN clicks. These live INSIDE editable elements, so the
         * generic intercept below (which stopImmediatePropagation + opens the
         * section/background editor) would otherwise swallow them:
         *   - .wpc-section-toggle  → the eye icon that shows/hides a section;
         *     without this guard, clicking it opened the background-color modal
         *     on section,background elements instead of toggling visibility.
         *   - .wpc-restore-btn     → "Click to restore" on a hidden-section bar.
         *   - [data-wpc-tour-dot]  → carousel dots, so the user can navigate to
         *     each slide and edit its image (EC-CAROUSEL-025).
         *   - [data-wpc-carousel-dot/prev/next] → EC-EDITOR-044 hero/Weebly
         *     carousels use the same hooks; without this guard the capture
         *     handler opens the section editor instead of switching slides.
         *   - [data-wpc-content-swap-btn] → EC-TAB-007 content-swap tab buttons.
         *   - [data-wpc-fx-thumb]         → EC-VISION-001 effect-slider thumb
         *     (gradient / blur / opacity sliders) so dragging works in edit mode.
         *
         * EC-EDIT-005b: the same swallowing killed two *page* features, because
         * their controls also sit inside editable regions:
         *   - [data-wpc-calc-var] / [data-wpc-calc-toggle] → EC-CALC-003 savings
         *     calculator. freezeScroll() preventDefault()s the pointerdown, so
         *     the sliders could not be dragged or keyboard-stepped at all and
         *     the calculator read as completely dead in edit mode.
         *   - [data-wpc-mstep-nav] → EC-ASSESS-001 wizard Next/Back buttons,
         *     stamped by the multi-step runtime as it wires them, so only
         *     buttons that actually drive navigation are exempted.
         * These are pure controls with no editable text of their own, so
         * letting their clicks through costs no editing surface. */
        if (e.target && e.target.closest &&
            e.target.closest('.wpc-section-toggle, .wpc-restore-btn, [data-wpc-tour-dot], [data-wpc-carousel-dot], [data-wpc-carousel-prev], [data-wpc-carousel-next], [data-wpc-content-swap-btn], [data-wpc-fx-thumb], [data-wpc-calc-var], [data-wpc-calc-toggle], [data-wpc-mstep-nav]')) {
            return;
        }
        /* EC-EDITOR-061: Once an element is live, every further click inside it
         * re-entered handleClick -> cleanup() -> startInlineEdit(), which focus()es
         * the element and collapses the caret to offset 0. The user could neither
         * click into the middle of a sentence nor drag-select a word to replace it:
         * mousedown set the selection, then the click that ended the gesture threw
         * it away. Leave clicks inside the element being edited to the browser. */
        var liveEdit = e.target && e.target.closest
            ? e.target.closest('[contenteditable="true"]')
            : null;
        if (liveEdit && liveEdit === activeEl) return;

        var editable = e.target && e.target.closest ? e.target.closest("[data-wpc-editable]") : null;
        if (!editable) return;
        freezeScroll(e);
        e.stopPropagation();
        lastClickX = e.clientX;
        lastClickY = e.clientY;
        try {
            handleClick(e, editable);
        } catch (err) {
            if (typeof console !== "undefined" && console.error) {
                console.error("[WPConvert Editor] handleClick error:", err);
            }
        }
        /* EC-EDITOR-032: Tab buttons are editable AND wired to EC-TAB-004 panel
         * switching. Stop the tab runtime from re-hiding inactive panels while
         * the user is editing button labels or panel content. */
        if (editable.hasAttribute("data-wpc-react-tab-btn")) {
            e.stopImmediatePropagation();
        }
    }, true);

    function initTabPanelsForEdit() {
        document.querySelectorAll("[data-wpc-react-tab-group]").forEach(function(group) {
            var btns = group.querySelectorAll("[data-wpc-react-tab-btn]");
            var scope = group.closest("section") || group.parentElement || document;
            var panels = scope.querySelectorAll("[data-wpc-react-tab-panel]");
            if (!panels.length) return;
            panels.forEach(function(panel, i) {
                panel.classList.add("wpc-tab-panel-edit-mode");
                panel.classList.remove("hidden", "opacity-0", "scale-95", "pointer-events-none");
                panel.classList.add("block", "opacity-100", "scale-100", "pointer-events-auto");
                var btn = btns[i];
                if (btn) {
                    panel.setAttribute("data-wpc-tab-label", (btn.textContent || "").trim());
                }
            });
        });
    }

    /* EC-EDITOR-044: Reveal carousel navigation chrome that conversion hides
     * (Weebly `.wslide-button-wrap { display:none }`, opacity-stacked slides). */
    function wpcEnsureCarouselId(container) {
        if (!container) return "";
        if (!container.getAttribute("data-wpc-id")) {
            var domId = container.id || "";
            if (domId) {
                container.setAttribute(
                    "data-wpc-id",
                    "wpc_carousel_" + domId.replace(/[^a-z0-9]/gi, "_").slice(0, 48)
                );
            } else {
                var firstImg = container.querySelector("[data-wpc-slide] img[data-wpc-id]");
                var seed = firstImg ? firstImg.getAttribute("data-wpc-id") : "carousel";
                container.setAttribute("data-wpc-id", "wpc_carousel_" + wpcMd5(seed).slice(0, 12));
