    function wpcReindexCarouselSlides(container) {
        if (!container) return;
        var slides = container.querySelectorAll("[data-wpc-slide]");
        slides.forEach(function(slide, i) {
            slide.setAttribute("data-wpc-slide", String(i));
            slide.classList.remove("opacity-100", "opacity-0", "pointer-events-none");
            if (i === 0) slide.classList.add("opacity-100");
            else slide.classList.add("opacity-0", "pointer-events-none");
        });
