    }

    function wpcGetCarouselSlideContext(imgEl) {
        if (!imgEl || !imgEl.closest) return null;
        var slide = imgEl.closest("[data-wpc-slide]");
        var carousel = slide ? slide.closest("[data-wpc-carousel=\"true\"]") : null;
        if (!slide || !carousel) return null;
        var slides = carousel.querySelectorAll("[data-wpc-slide]");
        if (slides.length < 2) return null;
        var track = carousel.querySelector(".wslide-slides");
        if (!track) return null;
        return { slide: slide, carousel: carousel, slides: slides, track: track };
    }

    function initCarouselsForEdit() {
        if (typeof window._wpcCarouselPauseAll === "function") {
            window._wpcCarouselPauseAll();
        }
        document.querySelectorAll('[data-wpc-carousel="true"]').forEach(function(container) {
            wpcEnsureCarouselId(container);
            container.classList.add("wpc-carousel-edit-mode");
            container.querySelectorAll(".wslide-button-wrap").forEach(function(wrap) {
                wrap.style.display = "block";
                wrap.style.opacity = "1";
                wrap.style.visibility = "visible";
            });
            container.querySelectorAll("[data-wpc-carousel-prev], [data-wpc-carousel-next]").forEach(function(btn) {
                btn.style.display = "inline-block";
                btn.style.opacity = "1";
                btn.style.pointerEvents = "auto";
            });
        });
    }

