    function init() {
        document.body.classList.add("wpconvert-editing");
        /* EC-EDITOR-033: Restore SPA virtual page after theme default showPage() */
        if (typeof window.wpconvertRestoreSpaView === "function") {
            window.wpconvertRestoreSpaView(true);
        }

        // Load editable manifest for fallback lookups (e.g. video URLs)
        var manifestUrl = (typeof wpcEditor !== "undefined" && wpcEditor.themeUrl ? wpcEditor.themeUrl : "") + "/assets/data/editable-manifest.json";
        try {
            var xhr = new XMLHttpRequest();
            xhr.open("GET", manifestUrl, true);
            xhr.onload = function() {
                if (xhr.status === 200) {
                    try { wpcEditableManifest = JSON.parse(xhr.responseText); } catch(e) {}
                }
            };
            xhr.send();
        } catch(e) {}

        // Add sibling overlays for video iframes/videos so clicks don't go to the media element
        function attachVideoOverlay(mediaEl) {
            var parent = mediaEl.parentNode;
            if (!parent) return;
            if (parent.querySelector(".wpc-video-overlay[data-wpc-id=\"" + (mediaEl.getAttribute("data-wpc-id") || "") + "\"]")) return;
            ensurePositioned(parent);
            var overlay = document.createElement("div");
            overlay.className = "wpc-video-overlay";
            overlay.setAttribute("data-wpc-id", mediaEl.getAttribute("data-wpc-id") || "");
            overlay.setAttribute("data-wpc-editable", "video");
            overlay._wpcMediaEl = mediaEl;
            mediaEl.removeAttribute("data-wpc-id");
            mediaEl.removeAttribute("data-wpc-editable");
            parent.insertBefore(overlay, mediaEl.nextSibling);
        }
        document.querySelectorAll('iframe[data-wpc-editable="video"]').forEach(attachVideoOverlay);
        document.querySelectorAll('video[data-wpc-editable="video"]').forEach(attachVideoOverlay);

        var els = document.querySelectorAll("[data-wpc-editable]");
        els.forEach(function(el) {
            el.addEventListener("mouseenter", showBadge);
            el.addEventListener("mouseleave", hideBadge);
        });

        /* EC-EDITOR-023: Neutralise transparent full-cover overlays that block editable elements.
         * Walk up from each editable to find absolutely-positioned transparent siblings
         * containing only links (clickfield pattern). Set pointer-events: none on them. */
        els.forEach(function(el) {
            var node = el.parentElement;
            for (var d = 0; d < 4 && node; d++, node = node.parentElement) {
                for (var i = 0; i < node.children.length; i++) {
                    var sib = node.children[i];
                    if (sib.contains(el) || sib.getAttribute("data-wpc-editable")) continue;
                    var cs = window.getComputedStyle(sib);
                    if (cs.position !== "absolute" && cs.position !== "fixed") continue;
                    var bg = cs.backgroundColor;
                    if (bg && bg !== "transparent" && bg !== "rgba(0, 0, 0, 0)") continue;
                    if (sib.querySelector("a") && !sib.querySelector("img, video, picture")) {
                        sib.style.pointerEvents = "none";
                    }
                }
            }
        });

        // EC-EDIT-004: Suppress hover badge when mouse enters a no-edit zone
        // (e.g. dynamic blog grid). The zone lives inside a section/background
        // editable, so entering it hides the parent's badge. Leaving it allows
        // the parent's badge to reappear on next mouseenter.
        document.querySelectorAll("[data-wpc-no-edit]").forEach(function(noEdit) {
            noEdit.addEventListener("mouseenter", function() {
                hideBadge();
                noEdit._wpcSuppressed = true;
            });
            noEdit.addEventListener("mouseleave", function() {
                noEdit._wpcSuppressed = false;
            });
        });
        initTabPanelsForEdit();
        initCarouselsForEdit();
        initSectionToggles();
        initHiddenSectionBars();
        initNavCtaFallback();
        initEditModeHelpPill();
        bindExitGuard();
    }

    function initEditModeHelpPill() {
        if (document.getElementById("wpc-edit-help-pill")) return;
        var helpUrl = (typeof wpcEditor !== "undefined" && wpcEditor.helpUrl) ? wpcEditor.helpUrl : "";
        if (!helpUrl) return;
        var pill = document.createElement("a");
        pill.id = "wpc-edit-help-pill";
        pill.className = "wpc-help-pill";
        pill.href = helpUrl;
        pill.target = "_blank";
        pill.rel = "noopener noreferrer";
        pill.textContent = "? What can I edit?";
        document.body.appendChild(pill);
    }

