            var pVid = el.parentElement.querySelector('[data-wpc-editable="video"]');
            if (pVid && !pVid.closest("section") !== !el.closest("section")) {
                // video is in a different section scope — ignore
            } else if (pVid) {
                return true;
            }
        }
