                var icls = img.className || "";
                var istyle = img.getAttribute("style") || "";
                if (img.getAttribute("data-wpc-editable") === "image" && /object.cover|object-fit\s*:\s*cover/i.test(icls + istyle)) {
                    return img;
                }
                if (/object.cover/.test(icls) || (img.offsetWidth >= section.offsetWidth * 0.8 && img.offsetHeight >= section.offsetHeight * 0.5)) {
                    return img;
                }
            }
        }
        return null;
    }

    // EC-EDITOR-033: Detect full-bleed hero background video (native <video> or autoplay iframe).
    function findHeroBgMedia(section) {
        if (!section || section.tagName !== "SECTION") return null;
        var heroImg = findHeroBgImg(section);
        if (heroImg) return { type: "image", el: heroImg };

        var heroVideoId = section.getAttribute("data-wpc-hero-video-id");
        if (heroVideoId) {
            var linked = document.querySelector('.wpc-video-overlay[data-wpc-id="' + heroVideoId.replace(/"/g, "") + '"]')
                || document.querySelector('[data-wpc-id="' + heroVideoId.replace(/"/g, "") + '"]');
            if (linked) return { type: "video", el: linked };
        }

        var containers = section.querySelectorAll('[class*="absolute"]');
        for (var i = 0; i < containers.length; i++) {
            var container = containers[i];
            var parentSection = container.closest("section");
            if (parentSection && parentSection !== section) continue;

            var overlay = container.querySelector('.wpc-video-overlay[data-wpc-editable="video"]');
            if (overlay) return { type: "video", el: overlay };

            var video = container.querySelector("video");
            if (video) {
                var vCls = video.className || "";
                var vParentCls = (video.parentElement && video.parentElement.className) || "";
                if (/object-cover|hero|video-hero|w-full|h-full|absolute|inset-0/.test(vCls + " " + vParentCls) || video.hasAttribute("autoplay")) {
                    return { type: "video", el: video };
                }
            }

            var iframe = container.querySelector("iframe");
            if (iframe) {
                var src = iframe.getAttribute("src") || "";
                if (/youtube|youtu\.be|vimeo|wistia|loom|mediadelivery|bunnycdn/i.test(src)) {
                    if (/background=1|autoplay=1|muted=1/.test(src)) {
                        return { type: "video", el: iframe };
                    }
                }
            }
        }

        var scoped = section.querySelector('[data-wpc-editable="video"], .wpc-video-overlay[data-wpc-editable="video"]');
        if (scoped) return { type: "video", el: scoped };
        return null;
    }

    /* EC-EDITOR-057: CSS-only hero backgrounds (Weebly parallax divs with inline
     * background-image, no <img>) — route section clicks to the background editor. */
    function findCssHeroBackgroundEl(scope) {
        if (!scope || !scope.querySelectorAll) return null;
        var root = scope.tagName === "SECTION" ? scope : (scope.closest ? scope.closest("section") : null);
        if (!root) root = scope;

        var stamped = root.querySelector('[data-wpc-css-hero-bg="1"][data-wpc-editable*="background"]');
        if (stamped) return stamped;

        var parallax = root.querySelector('[data-wpconvert-parallax-bg][data-wpc-editable*="background"]');
        if (parallax) return parallax;

        var candidates = root.querySelectorAll('[data-wpc-editable*="background"]');
        for (var i = 0; i < candidates.length; i++) {
            var el = candidates[i];
            var inline = el.getAttribute("style") || "";
            if (/background(-image)?\s*:[^;]*url\s*\(/i.test(inline)) return el;
            if (el.getAttribute("data-wpconvert-parallax-bg") !== null) return el;
            var cls = el.className || "";
            if (/parallax|wsite-section-bg-image|hero|banner/i.test(cls) && /url\s*\(/i.test(inline)) return el;
        }

        if (scope.getAttribute && scope.getAttribute("data-wpc-editable") && scope.getAttribute("data-wpc-editable").indexOf("background") !== -1) {
            var s = scope.getAttribute("style") || "";
            if (/url\s*\(/i.test(s)) return scope;
        }
        return null;
    }

    /* EC-EDITOR-048 / EC-EDITOR-052: Route a section click to its full-bleed hero
     * image/video when one exists, instead of opening the background popover. */
    function routeHeroMediaClick(el) {
        if (el && el.getAttribute && el.getAttribute("data-wpc-css-hero-bg") === "1") {
            if (el.classList) el.classList.remove("wpc-active");
            activeEl = el;
            el.classList.add("wpc-active");
            openBackgroundPopover(el, el.getAttribute("data-wpc-id"));
            return true;
        }

        var section = el && el.tagName === "SECTION" ? el : (el && el.closest ? el.closest("section") : null);
        if (!section) {
            var cssOnly = findCssHeroBackgroundEl(el);
            if (cssOnly) {
                if (el.classList) el.classList.remove("wpc-active");
                activeEl = cssOnly;
                cssOnly.classList.add("wpc-active");
                openBackgroundPopover(cssOnly, cssOnly.getAttribute("data-wpc-id"));
                return true;
            }
            return false;
        }
        var hm = findHeroBgMedia(section);
        if (hm && hm.el) {
            if (el.classList) el.classList.remove("wpc-active");
            activeEl = hm.el;
            hm.el.classList.add("wpc-active");
            if (hm.type === "image") {
                openImagePopover(hm.el);
            } else {
                openVideoPopover(hm.el);
            }
            return true;
        }

        var cssBg = findCssHeroBackgroundEl(section);
        if (cssBg) {
            if (el.classList) el.classList.remove("wpc-active");
            activeEl = cssBg;
            cssBg.classList.add("wpc-active");
            openBackgroundPopover(cssBg, cssBg.getAttribute("data-wpc-id"));
            return true;
        }
        return false;
    }

    /* EC-EDITOR-052: section,background elements need an explicit choice between
     * background editing and section visibility — not an immediate color popover. */
    function openSectionDualChooser(el) {
        cleanup();
        activeEl = el;
        el.classList.add("wpc-active");
        popover = document.createElement("div");
        popover.className = "wpc-popover wpc-section-dual-chooser";
        popover.innerHTML =
            '<div class="wpc-popover-title">Section options</div>' +
            '<p class="wpc-popover-hint">This section supports both layout and background edits.</p>' +
            '<button type="button" class="wpc-save-btn wpc-dual-bg-btn" style="width:100%;margin-bottom:8px;">Edit background</button>' +
            '<button type="button" class="wpc-cancel-btn wpc-dual-section-btn" style="width:100%;">Show / hide section</button>';
        document.body.appendChild(popover);
        positionPopover(el);
        popover.querySelector(".wpc-dual-bg-btn").onclick = function() {
            var bgId = el.getAttribute("data-wpc-bg-id") || el.getAttribute("data-wpc-id");
            cleanup();
            activeEl = el;
            el.classList.add("wpc-active");
            openBackgroundPopover(el, bgId);
        };
        popover.querySelector(".wpc-dual-section-btn").onclick = function() {
            cleanup();
            activeEl = el;
            el.classList.add("wpc-active");
            openSectionToggle(el);
        };
        onCancel = function() { cleanup(); };
    }

    function resolveHeroVideoEl(sectionOrBg) {
        var section = sectionOrBg.tagName === "SECTION" ? sectionOrBg : sectionOrBg.closest("section");
        if (!section) return null;
        var hm = findHeroBgMedia(section);
        return (hm && hm.type === "video") ? hm.el : null;
    }

    function initNavCtaFallback() {
        document.addEventListener("click", function(e) {
            var el = e.target && e.target.closest ? e.target.closest("a") : null;
            if (!el || !el.closest("nav, header")) return;
            var existing = el.getAttribute("data-wpc-editable");
            if (existing && existing !== "button") return;
            if (!existing) {
                var cls = (el.getAttribute("class") || "");
                var isCta = /\b(btn|button|cta)\b/i.test(cls) || /\bbg-(?!transparent|inherit)/.test(cls);
                if (!isCta) return;
                var text = (el.textContent || "").trim();
                var href = el.getAttribute("href") || "";
                var id = "wpc_navbtn_" + wpcMd5(text + href);
                el.setAttribute("data-wpc-id", id);
                el.setAttribute("data-wpc-editable", "button");
            }
            freezeScroll(e);
            lastClickX = e.clientX;
            lastClickY = e.clientY;
            cleanup();
            activeEl = el;
            el.classList.add("wpc-active");
            openButtonPopover(el);
        }, true);
    }

    function ensurePositioned(el) {
        if (window.getComputedStyle(el).position === "static") {
            el.style.position = "relative";
        }
    }

    /* EC-EDITOR-040b: srcset outranks src, so assigning a new src alone leaves
     * the browser painting the old picture and the swap looks like it silently
     * failed. EC-EDITOR-040 already drops srcset/sizes in the PHP override that
     * runs on the next page load; this is the live-preview half, without which
     * the user sees the original photo right through save and reasonably
     * concludes nothing happened (Base44 team portraits ship 1x/2x/3x srcset). */
    function setImgSrc(el, url) {
        if (!el) return;
        el.setAttribute("src", url);
        if (el.tagName === "IMG") {
            el.removeAttribute("srcset");
            el.removeAttribute("sizes");
        }
    }

    /* EC-EDITOR-042: <img> is a void element — appendChild() on it succeeds in
     * the DOM but the child is never rendered, so the hover badge for every
     * standalone editable image was silently invisible. Team portraits are the
     * common case: hovering a headshot showed no "Image" affordance at all and
     * the section outline was the only feedback, which reads as "I can't pick
     * the individual photo" (AI Leadit About page, Aug 10 2026).
     *
     * Anchor the badge to the target's viewport box on <body>. Re-hosting it on
     * the parent is NOT enough: media wrappers are routinely overflow-hidden
     * (these portraits sit in `.relative.aspect-[4/5].overflow-hidden`), which
     * clips a badge drawn above the image just as effectively as appendChild
     * dropped it. Fixed positioning on <body> escapes every ancestor's clipping
     * regardless of how the card is built. The badge is pointer-events:none and
     * exists only between mouseenter and mouseleave, so it cannot intercept
     * input or outlive the hover. */
    var VOID_BADGE_TAGS = { IMG: 1, INPUT: 1, VIDEO: 1, IFRAME: 1, EMBED: 1, OBJECT: 1, CANVAS: 1, HR: 1, BR: 1 };
    function appendBadge(el, badge) {
        if (!VOID_BADGE_TAGS[el.tagName]) {
            ensurePositioned(el);
            el.appendChild(badge);
            return;
        }
        var elRect = el.getBoundingClientRect();
        badge.classList.add("wpc-badge-void");
        badge.style.top = elRect.top + "px";
        badge.style.left = elRect.left + "px";
        document.body.appendChild(badge);
    }

    function initSectionToggles() {
        document.querySelectorAll('[data-wpc-editable]').forEach(function(el) {
            var type = el.getAttribute("data-wpc-editable");
            if (!type || type.indexOf("section") === -1) return;
            ensurePositioned(el);
            var btn = document.createElement("button");
            btn.className = "wpc-section-toggle";
            btn.innerHTML = "&#128065;";
            btn.title = "Toggle section visibility";
            btn.onclick = function(e) {
                e.preventDefault();
                e.stopPropagation();
                if (!isPro) {
                    cleanup();
                    activeEl = el;
                    el.classList.add("wpc-active");
                    showUpgradePrompt(el, "section");
                } else {
                    openSectionToggle(el);
                }
            };
            el.appendChild(btn);
        });
    }

    function initHiddenSectionBars() {
        document.querySelectorAll('[data-wpc-editable]').forEach(function(el) {
            var type = el.getAttribute("data-wpc-editable");
            if (!type || type.indexOf("section") === -1) return;
            if (window.getComputedStyle(el).display !== "none") return;
            el.setAttribute("data-wpc-hidden", "1");
            var bar = document.createElement("div");
            bar.className = "wpc-section-hidden-bar";
            bar.setAttribute("data-wpc-bar-for", el.getAttribute("data-wpc-id"));
            var label = el.querySelector("h1,h2,h3");
            bar.innerHTML = "Hidden: " + (label ? escAttr(label.textContent.trim()) : "Section") +
                ' <button class="wpc-restore-btn">Click to restore</button>';
            bar.querySelector(".wpc-restore-btn").onclick = function(ev) {
                ev.stopPropagation();
                var raw = el.getAttribute("style") || "";
                el.setAttribute("style", raw.replace(/display\s*:\s*[^;]*;?\s*/gi, ""));
                el.removeAttribute("data-wpc-hidden");
                bar.parentNode.removeChild(bar);
                saveEditEx(el, "section", "", { hidden: false });
            };
            el.parentNode.insertBefore(bar, el.nextSibling);
        });
    }

    /* ── Badges ── */
    var badgeLabels = { heading: "Heading", text: "Text", image: "Image", "image-hover-pair": "Image (hover card)", button: "Button", link: "Link", "social-link": "Social Link", section: "Hide Section", background: "Background", list: "List", video: "Video" };
    var currentBadge = null;
    function showBadge(e) {
        if (activeEl) return;
        // EC-EDIT-004: Don't show badge if any child no-edit zone is suppressed
        var el = e.currentTarget;
        var noEdits = el.querySelectorAll("[data-wpc-no-edit]");
        for (var k = 0; k < noEdits.length; k++) {
            if (noEdits[k]._wpcSuppressed) return;
        }
        hideBadge();
        // Ship 4c.6 / A7 — WC-managed sections defer to WooCommerce admin.
        // Inline edits on rendered product cards wouldn't persist (the data
        // lives on WC products, not in editor overrides), so the badge
        // becomes a deep-link affordance instead of an edit label.
        if (el.closest("[data-wpc-wc-managed]")) {
            var wb = document.createElement("div");
            wb.className = "wpc-badge wpc-badge-wc";
            wb.textContent = "Manage in WooCommerce \u2192";
            appendBadge(el, wb);
            currentBadge = wb;
            return;
        }
        var type = el.getAttribute("data-wpc-editable");
        var badgeType = (type && type.indexOf("background") !== -1) ? "background" : type;
        var heroSection = el.tagName === "SECTION" ? el : el.closest("section");
        if (heroSection) {
            var heroMedia = findHeroBgMedia(heroSection);
            // Only relabel section/background/video targets — not headings, text, or buttons inside the hero.
            if (heroMedia && heroMedia.type === "video" && (type === "video" || (type && type.indexOf("background") !== -1) || (type && type.indexOf("section") !== -1))) badgeType = "video";
            else if (type === "section" && heroMedia && heroMedia.type === "image") badgeType = "image";
        } else if (type === "section" && findHeroBgImg(el)) {
            badgeType = "image";
        }
        if (badgeType === "background" && detectVideoCard(el)) badgeType = "video";
        if (badgeType === "image" && el.getAttribute("data-wpc-img-pair")) badgeType = "image-hover-pair";
        var b = document.createElement("div");
        b.className = "wpc-badge";
        b.textContent = badgeLabels[badgeType] || badgeType || type;
        appendBadge(el, b);
        currentBadge = b;
    }
    function hideBadge() {
        if (currentBadge && currentBadge.parentNode) {
            currentBadge.parentNode.removeChild(currentBadge);
        }
        currentBadge = null;
    }

    /* ── Click handler ── */
    /* EC-EDITOR-021: stopPropagation so anchor/dropdown handlers do not run when editing */
    function freezeScroll(e) {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        var sx = window.pageXOffset || document.documentElement.scrollLeft;
        var sy = window.pageYOffset || document.documentElement.scrollTop;
        if (typeof jQuery !== "undefined") jQuery("html, body").stop(true);
        requestAnimationFrame(function() { window.scrollTo(sx, sy); });
    }
    function handleClick(e, el) {
        el = el || e.currentTarget;
        freezeScroll(e);
        lastClickX = e.clientX;
        lastClickY = e.clientY;
        // Ship 4c.6 / A7 — WC-managed sections: open the product in WC
        // admin instead of the inline editor. Per-card deep links are
        // stamped as data-wpc-wc-admin-url by the WC loop swap.
        var wcWrap = el.closest("[data-wpc-wc-managed]");
        if (wcWrap) {
            var wcCard = el.closest("[data-wpc-wc-admin-url]");
            var wcUrl = (wcCard && wcCard.getAttribute("data-wpc-wc-admin-url"))
                || "/wp-admin/edit.php?post_type=product";
            window.open(wcUrl, "_blank");
            return;
        }
        // EC-EDIT-004: If click originated inside a data-wpc-no-edit zone
        // (e.g. dynamic blog grid), don't open the section/background editor
        var noEdit = e.target.closest("[data-wpc-no-edit]");
        if (noEdit && el.contains(noEdit) && noEdit !== el) {
            return;
        }
        cleanup();
        activeEl = el;
        el.classList.add("wpc-active");
        var type = el.getAttribute("data-wpc-editable");

        if (type && type.indexOf("background") !== -1) {
            var heroVidBg = resolveHeroVideoEl(el);
            if (heroVidBg) {
                el.classList.remove("wpc-active");
                activeEl = heroVidBg;
                heroVidBg.classList.add("wpc-active");
                openVideoPopover(heroVidBg);
                return;
            }
            /* EC-EDITOR-052: dual section+background heroes should still reach the
             * background <img> before we open the color popover. */
            if (type.indexOf("section") !== -1 && routeHeroMediaClick(el)) {
                return;
            }
            if (detectVideoCard(el)) {
                var vChild = el.querySelector('[data-wpc-editable="video"]');
                if (!vChild && el.parentElement) {
                    var pVid = el.parentElement.querySelector('[data-wpc-editable="video"]');
                    if (pVid) {
                        var pSec = pVid.closest("section");
                        var elSec = el.closest("section");
                        if (!pSec || pSec === elSec) vChild = pVid;
                    }
                }
                if (!vChild) vChild = el.querySelector("img");
                if (vChild) {
                    el.classList.remove("wpc-active");
                    activeEl = vChild;
                    vChild.classList.add("wpc-active");
                    openVideoPopover(vChild);
                    return;
                }
            }
            var bgId = el.getAttribute("data-wpc-bg-id");
            if (bgId) {
                if (proTypes["background"] && !isPro) {
                    showUpgradePrompt(el, "background");
                    return;
                }
                /* EC-EDITOR-052: when both section and background are editable and
                 * there is no hero media to route to, ask what the user meant. */
                if (type.indexOf("section") !== -1 && el.tagName === "SECTION") {
                    openSectionDualChooser(el);
                    return;
                }
                openBackgroundPopover(el, bgId);
                return;
            }
        }

        if (type === "section" || (type && type.indexOf("section") !== -1 && type.indexOf("background") === -1)) {
            if (routeHeroMediaClick(el)) {
                return;
            }
            /* EC-EDITOR-054: Pure section editables are for show/hide — not the
             * background color popover (that path is for section,background). */
            openSectionToggle(el);
            return;
        }

        if (proTypes[type] && !isPro) {
            showUpgradePrompt(el, type);
            return;
        }

        if (type === "heading" || type === "text") {
            startInlineEdit(el, type);
        } else if (type === "image") {
            if (el.getAttribute("data-wpc-img-role") === "hover") {
                var pBaseId = el.getAttribute("data-wpc-img-pair");
                if (pBaseId) {
                    var baseImg = document.querySelector('img[data-wpc-id="' + pBaseId.replace(/"/g, "") + '"]');
                    if (baseImg) {
                        el.classList.remove("wpc-active");
                        activeEl = baseImg;
                        baseImg.classList.add("wpc-active");
                        openImagePopover(baseImg);
                        return;
                    }
                }
            }
            openImagePopover(el);
        } else if (type === "button") {
            openButtonPopover(el);
        } else if (type === "social-link") {
            openSocialLinkPopover(el);
        } else if (type === "link") {
            openLinkPopover(el);
        } else if (type === "background") {
            openBackgroundPopover(el);
        } else if (type === "list") {
            openListEditor(el);
        } else if (type === "video") {
            openVideoPopover(el);
        }
    }

    /* ── Inline text editing ── */
    function startInlineEdit(el, type) {
        originalValue = el.innerHTML;
        /* EC-EDITOR-038: mark everything that was already here, so the
           EC-EDITOR-031 typography reset can tell the page's own inline markup
           from whatever arrives during this session. Done before contenteditable
           so nothing the browser adds on focus gets mistaken for original. */
        try {
            var origNodes = el.querySelectorAll("*");
            for (var oi = 0; oi < origNodes.length; oi++) {
                origNodes[oi].setAttribute("data-wpc-orig", "1");
            }
        } catch (eOrig) {}
        el.setAttribute("contenteditable", "true");
        if (type === "heading") {
            el.classList.add("wpc-edit-heading");
        }
        el.focus();
        /* EC-EDITOR-063 then EC-EDITOR-061: clear the invisible node first so the
         * click-derived caret cannot resolve into it, then restore the user's
         * click point, then make sure the caret ended up inside styled markup. */
        wpcStripLeadingZwsp(el);
        wpcSeedCaretFromClick(el, lastClickX, lastClickY);
        wpcCaretIntoSkin(el);
        showToolbar(el, type);

        /* EC-EDITOR-043: Headings are single-line in the saved theme. Block Enter
         * (which inserts div/p) and flatten any wrappers the browser already added. */
        var inlineKeyHandler = null;
        var inlineInputHandler = null;
        if (type === "heading") {
            wpcNormalizeHeadingDom(el);
            inlineKeyHandler = function(e) {
                if (e.key === "Enter" && !e.metaKey && !e.ctrlKey) {
                    e.preventDefault();
                }
            };
            /* EC-EDITOR-060: only step in when the browser actually injected a
             * block wrapper (Enter, or a paste that slipped past the sanitizer).
             * Normalizing on every keystroke is what reseated the caret. */
            inlineInputHandler = function() {
                if (el.querySelector("div, p")) wpcNormalizeHeadingDom(el);
            };
            el.addEventListener("keydown", inlineKeyHandler);
            el.addEventListener("input", inlineInputHandler);
        } else if (type === "text") {
            inlineKeyHandler = function(e) {
                if (e.key === "Enter" && !e.shiftKey && !e.metaKey && !e.ctrlKey) {
                    e.preventDefault();
                    try {
                        document.execCommand("insertLineBreak");
                    } catch (errBr) {
                        document.execCommand("insertHTML", false, "<br>");
                    }
                }
            };
            el.addEventListener("keydown", inlineKeyHandler);
        }
        el._wpcInlineKeyHandler = inlineKeyHandler;
        el._wpcInlineInputHandler = inlineInputHandler;

        /* EC-EDITOR-031: Sanitize pasted rich text so it inherits the section's
           font instead of importing foreign typography. Rich clipboard sources
           (ChatGPT, Word, Google Docs) carry inline style="font-size/font-family/
           color", <font> tags, and <span class="..."> wrappers whose inline styles
           win over the element's CSS classes. Intercept paste, sanitize, and
           insert at the caret. Headings collapse to a single line of clean text;
           text blocks keep only basic semantic formatting (strong/em/u/a/br). */
        var pasteHandler = function(e) {
            e.preventDefault();
            var cd = e.clipboardData || window.clipboardData;
            if (!cd || !cd.getData) return;
            var html = "";
            try { html = cd.getData("text/html"); } catch (err) { html = ""; }
            var text = "";
            try { text = cd.getData("text/plain"); } catch (err2) { text = ""; }
            var cleanHtml;
            if (type === "heading") {
                /* Headings are single-line: paste plain text only. */
                var t = text || (html ? html.replace(/<[^>]+>/g, "") : "");
                cleanHtml = escapeHtml(t.replace(/\s+/g, " ").trim());
            } else if (html) {
                cleanHtml = wpcSanitizePastedHtml(html);
            } else {
                cleanHtml = escapeHtml(text).replace(/\r\n|\r|\n/g, "<br>");
            }
            insertHtmlAtCaret(cleanHtml);
        };
        el.addEventListener("paste", pasteHandler);
        el._wpcPasteHandler = pasteHandler;
    }

    /* EC-EDITOR-031: Plain-text escape for safe insertion. */
    function escapeHtml(s) {
        return String(s == null ? "" : s)
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;");
    }

    /* EC-EDITOR-031: Strip foreign typography from pasted HTML. Keeps only a
       small allowlist of semantic tags; removes style/class/font-size/font-family/
       color/align attributes and unwraps everything else (span, font, div, p…)
       so the result inherits the editable element's font. */
    function wpcSanitizePastedHtml(html) {
        var ALLOWED = { A: 1, B: 1, STRONG: 1, I: 1, EM: 1, U: 1, BR: 1 };
        var container = document.createElement("div");
        container.innerHTML = html;

        /* Drop dangerous / noise nodes entirely (but NOT <font> — that must be
           UNWRAPPED below so its text children survive; deleting it would discard
           the pasted copy). */
        var kill = container.querySelectorAll("script,style,meta,link,title,head,noscript,o\\:p");
        for (var k = 0; k < kill.length; k++) {
            if (kill[k].parentNode) kill[k].parentNode.removeChild(kill[k]);
        }

        function clean(node) {
            var children = Array.prototype.slice.call(node.childNodes);
            for (var i = 0; i < children.length; i++) {
                var child = children[i];
                if (child.nodeType === 1) {
                    var tag = child.tagName.toUpperCase();
                    clean(child);
                    if (ALLOWED[tag]) {
                        /* Strip ALL attributes except href on anchors — this is
                           where font-size/font-family/color/class hide. */
                        var attrs = Array.prototype.slice.call(child.attributes);
                        for (var a = 0; a < attrs.length; a++) {
                            var name = attrs[a].name.toLowerCase();
                            if (tag === "A" && name === "href") continue;
                            child.removeAttribute(attrs[a].name);
                        }
                        child.removeAttribute("style");
                        child.removeAttribute("class");
                    } else {
                        /* Unwrap: replace the element with its (cleaned) children.
                           Block-level tags (P, DIV, LI, H1-6) become a line break
                           so paragraph structure survives as <br>. */
                        var isBlock = /^(P|DIV|LI|UL|OL|H[1-6]|SECTION|ARTICLE|HEADER|FOOTER|BLOCKQUOTE|TR)$/.test(tag);
                        while (child.firstChild) {
                            node.insertBefore(child.firstChild, child);
                        }
                        if (isBlock) {
                            node.insertBefore(document.createElement("br"), child);
                        }
                        node.removeChild(child);
                    }
                } else if (child.nodeType !== 3) {
                    /* Comments / others: remove. */
                    node.removeChild(child);
                }
            }
        }
        clean(container);

        /* Collapse runs of <br> and trim leading/trailing breaks. */
        return container.innerHTML
            .replace(/(?:\s*<br\s*\/?>\s*){3,}/gi, "<br><br>")
            .replace(/^(?:\s*<br\s*\/?>\s*)+/i, "")
            .replace(/(?:\s*<br\s*\/?>\s*)+$/i, "");
    }

    /* EC-EDITOR-031: Insert sanitized HTML at the current caret position using
       the Selection/Range API (replaces any selected text). */
    function insertHtmlAtCaret(cleanHtml) {
        var sel = window.getSelection ? window.getSelection() : null;
        if (!sel || !sel.rangeCount) {
            document.execCommand("insertText", false, (cleanHtml || "").replace(/<[^>]+>/g, ""));
            return;
        }
        var range = sel.getRangeAt(0);
        range.deleteContents();
        var temp = document.createElement("div");
        temp.innerHTML = cleanHtml;
        var frag = document.createDocumentFragment();
        var node, lastNode;
        while ((node = temp.firstChild)) {
            lastNode = frag.appendChild(node);
        }
        range.insertNode(frag);
        if (lastNode) {
            range = range.cloneRange();
            range.setStartAfter(lastNode);
            range.collapse(true);
            sel.removeAllRanges();
            sel.addRange(range);
        }
    }

    function showToolbar(el, type) {
        toolbar = document.createElement("div");
        toolbar.className = "wpc-toolbar";

        var saveBtn = document.createElement("button");
        saveBtn.className = "wpc-save-btn";
        saveBtn.textContent = "Save";
        saveBtn.onclick = function() {
            var html = el.innerHTML;
            if (type === "heading") html = wpcNormalizeHeadingHtml(html);
            saveEdit(el, type, html);
        };

        var cancelBtn = document.createElement("button");
        cancelBtn.className = "wpc-cancel-btn";
        cancelBtn.textContent = "Cancel";
        cancelBtn.onclick = function() { el.innerHTML = originalValue; cleanup(); };

        var resetBtn = document.createElement("button");
        resetBtn.className = "wpc-reset-btn";
        resetBtn.textContent = "Reset";
        resetBtn.onclick = function() { resetEdit(el); };

        toolbar.appendChild(saveBtn);
        toolbar.appendChild(cancelBtn);
        toolbar.appendChild(resetBtn);
        document.body.appendChild(toolbar);
        positionToolbar(el);
    }

    function positionToolbar(el) {
        if (!toolbar) return;
        var top, left;
        if (lastClickX || lastClickY) {
            top = lastClickY + 12;
            left = lastClickX - 60;
        } else {
            var rect = el.getBoundingClientRect();
            top = rect.bottom + 8;
            left = rect.left;
        }
        if (top + 40 > window.innerHeight) top = (lastClickY || window.innerHeight / 2) - 44;
        if (top < 10) top = 10;
        if (left < 10) left = 10;
        var tw = toolbar.offsetWidth || 200;
        if (left + tw > window.innerWidth) left = window.innerWidth - tw - 10;
        toolbar.style.top = top + "px";
        toolbar.style.left = left + "px";
    }

    function postResetWpcId(wpcId) {
        var fd = new FormData();
        fd.append("action", "wpconvert_reset_edit");
        fd.append("nonce", nonce);
        fd.append("wpc_id", wpcId);
        return fetch(ajax, { method: "POST", credentials: "same-origin", body: fd }).then(function(r) { return r.json(); });
    }

    function reloadAfterReset() {
        var baseUrl = window.location.href
            .replace(/([?&])_wpc_t=\d+/, "$1")
            .replace(/[?&]$/, "");
        var sep = baseUrl.indexOf("?") !== -1 ? "&" : "?";
        var freshUrl = baseUrl + sep + "_wpc_t=" + Date.now();
        fetch(freshUrl, { cache: "no-store", credentials: "same-origin" })
            .finally(function() {
                window.location.replace(freshUrl);
            });
    }

    function resetImagePair(baseEl, hoverEl) {
        var id1 = baseEl.getAttribute("data-wpc-id");
        var id2 = hoverEl.getAttribute("data-wpc-id");
        postResetWpcId(id1)
            .then(function(d1) {
                if (!d1 || !d1.success) {
                    alert("Reset failed: " + ((d1 && d1.data) || "Unknown error"));
                    cleanup();
                    return null;
                }
                return postResetWpcId(id2);
            })
            .then(function(d2) {
                if (d2 === null) return;
                if (!d2 || !d2.success) {
                    alert("Reset failed: " + ((d2 && d2.data) || "Unknown error"));
                    cleanup();
                    return;
                }
                cleanup();
                reloadAfterReset();
            })
            .catch(function(err) { alert("Reset error: " + err.message); cleanup(); });
    }

    /* ── Image popover ── */
    function openImagePopover(el) {
        var pairId = el.getAttribute("data-wpc-img-pair") || "";
        var partner = null;
        var baseEl = el;
        var hoverEl = null;
        if (pairId) {
            partner = document.querySelector('img[data-wpc-id="' + pairId.replace(/"/g, "") + '"]');
        }
        if (partner && el.getAttribute("data-wpc-editable") === "image" && partner.getAttribute("data-wpc-editable") === "image") {
            if (el.getAttribute("data-wpc-img-role") === "hover") {
                hoverEl = el;
                baseEl = partner;
            } else {
                baseEl = el;
                hoverEl = partner;
            }
        } else {
            baseEl = el;
            hoverEl = null;
        }

        var originalBaseSrc = baseEl.getAttribute("src") || "";
        var originalBaseAlt = baseEl.getAttribute("alt") || "";
        var originalHoverSrc = hoverEl ? (hoverEl.getAttribute("src") || "") : "";
        var originalHoverAlt = hoverEl ? (hoverEl.getAttribute("alt") || "") : "";

        originalValue = originalBaseSrc;

        // Logo / linked images: if the image sits inside an <a>, let the user edit
        // the link URL from the same popover. Only offered for single (non-hover) images.
        var logoAnchor = (!hoverEl && el.closest) ? el.closest("a") : null;
        var originalAnchorHref = logoAnchor ? (logoAnchor.getAttribute("href") || "") : "";

        var carouselCtx = !hoverEl ? wpcGetCarouselSlideContext(baseEl) : null;

        popover = document.createElement("div");
        popover.className = "wpc-popover";
        if (hoverEl) {
            popover.innerHTML =
                '<label>Default image</label>' +
                '<input type="url" class="wpc-img-url" value="' + escAttr(originalBaseSrc) + '">' +
                '<label>Alt text (default)</label>' +
                '<input type="text" class="wpc-img-alt" value="' + escAttr(originalBaseAlt) + '">' +
                '<div style="margin-bottom:10px;"><button type="button" class="wpc-media-btn wpc-media-btn-base" style="width:100%;padding:8px;border:1px dashed #94a3b8;border-radius:6px;background:#f8fafc;cursor:pointer;font-size:12px;color:#475569;">Choose default from Media Library</button></div>' +
                '<label>Hover image</label>' +
                '<input type="url" class="wpc-img-hover-url" value="' + escAttr(originalHoverSrc) + '">' +
                '<label>Alt text (hover)</label>' +
                '<input type="text" class="wpc-img-hover-alt" value="' + escAttr(originalHoverAlt) + '">' +
                '<div style="margin-bottom:10px;"><button type="button" class="wpc-media-btn wpc-media-btn-hover" style="width:100%;padding:8px;border:1px dashed #94a3b8;border-radius:6px;background:#f8fafc;cursor:pointer;font-size:12px;color:#475569;">Choose hover from Media Library</button></div>' +
                '<div class="wpc-popover-actions">' +
                  '<button class="wpc-save-btn" style="background:#22c55e;color:#fff;">Save</button>' +
                  '<button class="wpc-cancel-btn" style="background:#e2e8f0;color:#334155;">Cancel</button>' +
                  '<button class="wpc-reset-btn" style="background:transparent;color:#f87171;text-decoration:underline;">Reset</button>' +
                '</div>';
        } else {
            popover.innerHTML =
                '<label>Image URL</label>' +
                '<input type="url" class="wpc-img-url" value="' + escAttr(originalBaseSrc) + '">' +
                '<label>Alt Text</label>' +
                '<input type="text" class="wpc-img-alt" value="' + escAttr(originalBaseAlt) + '">' +
                '<div style="margin-bottom:10px;"><button type="button" class="wpc-media-btn" style="width:100%;padding:8px;border:1px dashed #94a3b8;border-radius:6px;background:#f8fafc;cursor:pointer;font-size:12px;color:#475569;">Choose from Media Library</button></div>' +
                (carouselCtx ? '<button type="button" class="wpc-remove-carousel-slide-btn" style="width:100%;margin-bottom:10px;padding:8px;border:1px solid #fecaca;border-radius:6px;background:#fef2f2;cursor:pointer;font-size:12px;color:#b91c1c;font-weight:600;">Remove from carousel</button>' : '') +
                (logoAnchor && isPro ? ('<label>Link URL</label>' +
                '<input type="url" class="wpc-img-link" value="' + escAttr(originalAnchorHref) + '" placeholder="https://example.com/">') : '') +
                '<div class="wpc-popover-actions">' +
                  '<button class="wpc-save-btn" style="background:#22c55e;color:#fff;">Save</button>' +
                  '<button class="wpc-cancel-btn" style="background:#e2e8f0;color:#334155;">Cancel</button>' +
                  '<button class="wpc-reset-btn" style="background:transparent;color:#f87171;text-decoration:underline;">Reset</button>' +
                '</div>';
        }

        document.body.appendChild(popover);
        positionPopover(baseEl);

        var urlInput = popover.querySelector(".wpc-img-url");
        if (urlInput) {
            urlInput.addEventListener("input", function() {
                var v = urlInput.value.trim();
                if (v) setImgSrc(baseEl, v);
            });
        }
        if (hoverEl) {
            var hoverUrlInp = popover.querySelector(".wpc-img-hover-url");
            if (hoverUrlInp) {
                hoverUrlInp.addEventListener("input", function() {
                    var v = hoverUrlInp.value.trim();
                    if (v) setImgSrc(hoverEl, v);
                });
            }
        }

        popover.querySelector(".wpc-save-btn").onclick = function() {
            if (hoverEl) {
                var urlB = popover.querySelector(".wpc-img-url").value;
                var altB = popover.querySelector(".wpc-img-alt").value;
                var urlH = popover.querySelector(".wpc-img-hover-url").value;
                var altH = popover.querySelector(".wpc-img-hover-alt").value;
                setImgSrc(baseEl, urlB);
                if (altB) baseEl.setAttribute("alt", altB); else baseEl.removeAttribute("alt");
                setImgSrc(hoverEl, urlH);
                if (altH) hoverEl.setAttribute("alt", altH); else hoverEl.removeAttribute("alt");
                var fdB = buildSaveFormData(baseEl.getAttribute("data-wpc-id"), "image", urlB, { href: "", alt: altB });
                var fdH = buildSaveFormData(hoverEl.getAttribute("data-wpc-id"), "image", urlH, { href: "", alt: altH });
                cleanup();
                Promise.all([postSaveFormData(fdB), postSaveFormData(fdH)])
                    .then(function(results) {
                        var ok = results[0] && results[0].success && results[1] && results[1].success;
                        if (!ok) {
                            alert("Save failed: " + ((results[0] && results[0].data) || (results[1] && results[1].data) || "Unknown error"));
                            return;
                        }
                        baseEl.classList.add("wpc-flash-success");
                        hoverEl.classList.add("wpc-flash-success");
                        setTimeout(function() {
                            baseEl.classList.remove("wpc-flash-success");
                            hoverEl.classList.remove("wpc-flash-success");
                        }, 700);
                        bustCache();
                    })
                    .catch(function(err) { alert("Save error: " + err.message); });
            } else {
                var url = urlInput.value;
                var alt = popover.querySelector(".wpc-img-alt").value;
                var linkInp = popover.querySelector(".wpc-img-link");
                var linkHref = linkInp ? linkInp.value.trim() : "";
                setImgSrc(el, url);
                if (alt) el.setAttribute("alt", alt);
                if (logoAnchor && linkHref) logoAnchor.setAttribute("href", linkHref);
                saveEdit(el, "image", url, linkHref, alt);
            }
        };
        onCancel = function() {
            baseEl.setAttribute("src", originalBaseSrc);
            baseEl.setAttribute("alt", originalBaseAlt);
            if (hoverEl) {
                hoverEl.setAttribute("src", originalHoverSrc);
                hoverEl.setAttribute("alt", originalHoverAlt);
            }
            if (logoAnchor) logoAnchor.setAttribute("href", originalAnchorHref);
        };
        popover.querySelector(".wpc-cancel-btn").onclick = function() { onCancel(); onCancel = null; cleanup(); };
        popover.querySelector(".wpc-reset-btn").onclick = function() {
            onCancel = null;
            if (hoverEl) {
                resetImagePair(baseEl, hoverEl);
            } else {
                resetEdit(el);
            }
        };
        var removeSlideBtn = popover.querySelector(".wpc-remove-carousel-slide-btn");
        if (removeSlideBtn && carouselCtx) {
            removeSlideBtn.onclick = function() {
                if (!confirm("Remove this slide from the carousel?")) return;
                var ctx = carouselCtx;
                var track = ctx.track;
                var carousel = ctx.carousel;
                ctx.slide.remove();
                wpcReindexCarouselSlides(carousel);
                wpcEnsureCarouselId(carousel);
                onCancel = null;
                cleanup();
                saveEditEx(carousel, "carousel-slides", track.innerHTML, {});
            };
        }
        var btnBase = popover.querySelector(".wpc-media-btn-base");
        var btnHover = popover.querySelector(".wpc-media-btn-hover");
        var btnSingle = popover.querySelector(".wpc-media-btn");
        if (btnBase) btnBase.onclick = function() { openMediaLibrary(baseEl, ".wpc-img-url"); };
        if (btnHover) btnHover.onclick = function() { openMediaLibrary(hoverEl, ".wpc-img-hover-url"); };
        if (btnSingle) btnSingle.onclick = function() { openMediaLibrary(el); };
    }

    function openMediaLibrary(imgEl, urlInputSelector) {
        if (typeof wp === "undefined" || !wp.media) {
            alert("Media Library not available. Please enter the URL manually.");
            return;
        }
        var savedPopover = popover;
        var savedActive = activeEl;
        var urlSel = urlInputSelector || ".wpc-img-url";
        // EC-EDITOR-039: hide the edit popover while WP media modal is open
        if (savedPopover) savedPopover.style.display = "none";
        var frame = wp.media({ title: "Select Image", multiple: false, library: { type: "image" } });
        frame.on("close", function() {
          if (savedPopover) {
            savedPopover.style.display = "";
            positionPopover(activeEl || savedActive);
          }
        });
        frame.on("select", function() {
            var attachment = frame.state().get("selection").first().toJSON();
            if (!attachment || !attachment.url) return;
            var p = popover || savedPopover;
            if (!p) return;
            if (!p.parentNode) document.body.appendChild(p);
            popover = p;
            if (!activeEl && savedActive) {
                activeEl = savedActive;
                savedActive.classList.add("wpc-active");
            }
            var urlInp = p.querySelector(urlSel);
            var altInp = p.querySelector(urlSel.indexOf("hover") !== -1 ? ".wpc-img-hover-alt" : ".wpc-img-alt");
            if (urlInp) {
                urlInp.value = attachment.url;
                setImgSrc(imgEl, attachment.url);
            }
            if (altInp && attachment.alt && attachment.alt.trim()) altInp.value = attachment.alt;
        });
        frame.open();
    }

    /* ── Button popover ── */
    function openButtonPopover(el) {
        var btnText = "";
        var clone = el.cloneNode(true);
        var svgs = clone.querySelectorAll("svg");
        svgs.forEach(function(s) { s.remove(); });
        btnText = clone.textContent.trim();
        originalValue = btnText;
        var cs = window.getComputedStyle(el);
        var btnBg = (cs.backgroundColor && cs.backgroundColor !== "rgba(0, 0, 0, 0)" && cs.backgroundColor !== "transparent") ? rgbToHex(cs.backgroundColor) : "";
        var btnColor = (cs.color && cs.color !== "rgba(0, 0, 0, 0)") ? rgbToHex(cs.color) : "";

        popover = document.createElement("div");
        popover.className = "wpc-popover";
        popover.innerHTML =
            '<label>Button Text</label>' +
            '<input type="text" class="wpc-btn-text" value="' + escAttr(btnText) + '">' +
            '<label>Link URL</label>' +
            '<input type="url" class="wpc-btn-href" value="' + escAttr(el.getAttribute("href") || "") + '">' +
            '<label>Button Color</label>' +
            '<div class="wpc-btn-color-row" style="display:flex;gap:8px;align-items:center;margin-bottom:10px;">' +
              '<input type="color" class="wpc-btn-bg" value="' + (btnBg || "#22c55e") + '" title="Background">' +
              '<input type="text" class="wpc-btn-bg-hex" value="' + escAttr(btnBg || "") + '" placeholder="#hex" style="flex:1;max-width:80px;">' +
            '</div>' +
            '<label>Text Color</label>' +
            '<div class="wpc-btn-color-row" style="display:flex;gap:8px;align-items:center;margin-bottom:10px;">' +
              '<input type="color" class="wpc-btn-fg" value="' + (btnColor || "#ffffff") + '" title="Text color">' +
              '<input type="text" class="wpc-btn-fg-hex" value="' + escAttr(btnColor || "") + '" placeholder="#hex" style="flex:1;max-width:80px;">' +
            '</div>' +
            '<div class="wpc-popover-actions">' +
              '<button class="wpc-save-btn" style="background:#22c55e;color:#fff;">Save</button>' +
              '<button class="wpc-cancel-btn" style="background:#e2e8f0;color:#334155;">Cancel</button>' +
              '<button class="wpc-reset-btn" style="background:transparent;color:#f87171;text-decoration:underline;">Reset</button>' +
            '</div>';

        document.body.appendChild(popover);
        positionPopover(el);

        var bgPicker = popover.querySelector(".wpc-btn-bg");
        var bgHex = popover.querySelector(".wpc-btn-bg-hex");
        var fgPicker = popover.querySelector(".wpc-btn-fg");
        var fgHex = popover.querySelector(".wpc-btn-fg-hex");
        bgPicker.addEventListener("input", function() { bgHex.value = bgPicker.value; });
        bgHex.addEventListener("input", function() { if (/^#[0-9a-f]{6}$/i.test(bgHex.value)) bgPicker.value = bgHex.value; });
        fgPicker.addEventListener("input", function() { fgHex.value = fgPicker.value; });
        fgHex.addEventListener("input", function() { if (/^#[0-9a-f]{6}$/i.test(fgHex.value)) fgPicker.value = fgHex.value; });

        popover.querySelector(".wpc-save-btn").onclick = function() {
            var text = popover.querySelector(".wpc-btn-text").value;
            var href = popover.querySelector(".wpc-btn-href").value;
            var bgColor = popover.querySelector(".wpc-btn-bg-hex").value.trim();
            var textColor = popover.querySelector(".wpc-btn-fg-hex").value.trim();
            if (href) el.setAttribute("href", href);
            if (text) {
                var updated = false;
                for (var i = 0; i < el.childNodes.length; i++) {
                    if (el.childNodes[i].nodeType === 3 && el.childNodes[i].nodeValue.trim()) {
                        el.childNodes[i].nodeValue = text;
                        updated = true;
                        break;
                    }
                }
                if (!updated) {
                    var spans = el.querySelectorAll("span, button");
                    for (var j = 0; j < spans.length; j++) {
                        if (spans[j].textContent.trim()) {
                            spans[j].textContent = text;
                            break;
                        }
                    }
                }
            }
            if (bgColor) el.style.backgroundColor = bgColor;
            if (textColor) el.style.color = textColor;
            saveEditEx(el, "button", text, { href: href, bgColor: bgColor || "", textColor: textColor || "" });
        };
        popover.querySelector(".wpc-cancel-btn").onclick = function() { cleanup(); };
        popover.querySelector(".wpc-reset-btn").onclick = function() { resetEdit(el); };
    }

    /* ── Social link popover ── */
    function openSocialLinkPopover(el) {
        var network = el.getAttribute("data-wpc-social") || "social";
        var networkLabel = network.charAt(0).toUpperCase() + network.slice(1);
        var currentHref = el.getAttribute("href") || "";
        if (currentHref === "#") currentHref = "";
        originalValue = currentHref;
        var isBlank = el.getAttribute("target") === "_blank";

        popover = document.createElement("div");
        popover.className = "wpc-popover";
        popover.innerHTML =
            '<label style="font-size:13px;font-weight:600;margin-bottom:6px;display:flex;align-items:center;gap:6px;">' +
              '<span style="display:inline-flex;align-items:center;justify-content:center;width:24px;height:24px;background:rgba(59,130,246,0.1);border-radius:6px;">' +
                (el.querySelector("svg") ? el.querySelector("svg").outerHTML.replace(/width="[^"]*"/, 'width="14"').replace(/height="[^"]*"/, 'height="14"') : '') +
              '</span>' +
              networkLabel + ' Link</label>' +
            '<input type="url" class="wpc-social-href" value="' + escAttr(currentHref) + '" placeholder="https://' + network + '.com/yourprofile">' +
            '<label style="display:flex;align-items:center;gap:6px;margin-bottom:10px;text-transform:none;font-size:12px;cursor:pointer;">' +
              '<input type="checkbox" class="wpc-social-blank"' + (isBlank ? " checked" : "") + '> Open in new tab' +
            '</label>' +
            '<div class="wpc-popover-actions">' +
              '<button class="wpc-save-btn" style="background:#22c55e;color:#fff;">Save</button>' +
              '<button class="wpc-cancel-btn" style="background:#e2e8f0;color:#334155;">Cancel</button>' +
              '<button class="wpc-reset-btn" style="background:transparent;color:#f87171;text-decoration:underline;">Reset</button>' +
            '</div>';

        document.body.appendChild(popover);
        positionPopover(el);

        popover.querySelector(".wpc-save-btn").onclick = function() {
            var href = popover.querySelector(".wpc-social-href").value.trim();
            var blank = popover.querySelector(".wpc-social-blank").checked;
            if (href) {
                el.setAttribute("href", href);
            }
            if (blank) {
                el.setAttribute("target", "_blank");
                el.setAttribute("rel", "noopener noreferrer");
            } else {
                el.removeAttribute("target");
                el.removeAttribute("rel");
            }
            saveEditEx(el, "social-link", href, { href: href, target: blank ? "_blank" : "" });
        };
        popover.querySelector(".wpc-cancel-btn").onclick = function() { cleanup(); };
        popover.querySelector(".wpc-reset-btn").onclick = function() { resetEdit(el); };
    }

    /* ── Link popover ── */
    function openLinkPopover(el) {
        var linkText = el.textContent.trim();
        originalValue = linkText;
        var currentHref = el.getAttribute("href") || "";
        var isBlank = el.getAttribute("target") === "_blank";

        popover = document.createElement("div");
        popover.className = "wpc-popover";
        popover.innerHTML =
            '<label>Link Text</label>' +
            '<input type="text" class="wpc-link-text" value="' + escAttr(linkText) + '">' +
            '<label>URL</label>' +
            '<input type="url" class="wpc-link-href" value="' + escAttr(currentHref) + '">' +
            '<label style="display:flex;align-items:center;gap:6px;margin-bottom:10px;text-transform:none;font-size:12px;cursor:pointer;">' +
              '<input type="checkbox" class="wpc-link-blank"' + (isBlank ? " checked" : "") + '> Open in new tab' +
            '</label>' +
            '<div class="wpc-popover-actions">' +
              '<button class="wpc-save-btn" style="background:#22c55e;color:#fff;">Save</button>' +
              '<button class="wpc-cancel-btn" style="background:#e2e8f0;color:#334155;">Cancel</button>' +
              '<button class="wpc-reset-btn" style="background:transparent;color:#f87171;text-decoration:underline;">Reset</button>' +
            '</div>';

        document.body.appendChild(popover);
        positionPopover(el);

        popover.querySelector(".wpc-save-btn").onclick = function() {
            var text = popover.querySelector(".wpc-link-text").value;
            var href = popover.querySelector(".wpc-link-href").value;
            var blank = popover.querySelector(".wpc-link-blank").checked;
            if (href) el.setAttribute("href", href);
            if (blank) { el.setAttribute("target", "_blank"); el.setAttribute("rel", "noopener noreferrer"); }
            else { el.removeAttribute("target"); }
            if (text) {
                var updated = false;
                for (var i = 0; i < el.childNodes.length; i++) {
                    if (el.childNodes[i].nodeType === 3 && el.childNodes[i].nodeValue.trim()) {
                        el.childNodes[i].nodeValue = text; updated = true; break;
                    }
                }
                if (!updated) el.textContent = text;
            }
            saveEditEx(el, "link", text, { href: href, target: blank ? "_blank" : "" });
        };
        popover.querySelector(".wpc-cancel-btn").onclick = function() { cleanup(); };
        popover.querySelector(".wpc-reset-btn").onclick = function() { resetEdit(el); };
    }

    /* ── Section visibility toggle ── */
    function openSectionToggle(el) {
        cleanup();
        activeEl = el;
        el.classList.add("wpc-active");
        var isHidden = el.style.display === "none" || el.getAttribute("data-wpc-hidden") === "1";
        var msg = isHidden ? "Show this section?" : "Hide this section?";
        if (!confirm(msg)) { cleanup(); return; }
        var newHidden = !isHidden;
        if (newHidden) {
            el.setAttribute("data-wpc-hidden", "1");
            var bar = document.createElement("div");
            bar.className = "wpc-section-hidden-bar";
            bar.setAttribute("data-wpc-bar-for", el.getAttribute("data-wpc-id"));
            var label = el.querySelector("h1,h2,h3");
            bar.innerHTML = "Hidden: " + (label ? escAttr(label.textContent.trim()) : "Section") +
                ' <button class="wpc-restore-btn">Click to restore</button>';
            bar.querySelector(".wpc-restore-btn").onclick = function(ev) {
                ev.stopPropagation();
                var raw = el.getAttribute("style") || "";
                el.setAttribute("style", raw.replace(/display\s*:\s*[^;]*;?\s*/gi, ""));
                el.removeAttribute("data-wpc-hidden");
                bar.parentNode.removeChild(bar);
                saveEditEx(el, "section", "", { hidden: false });
            };
            el.parentNode.insertBefore(bar, el.nextSibling);
            el.style.display = "none";
        } else {
            var raw = el.getAttribute("style") || "";
            el.setAttribute("style", raw.replace(/display\s*:\s*[^;]*;?\s*/gi, ""));
            el.removeAttribute("data-wpc-hidden");
            var existBar = document.querySelector('[data-wpc-bar-for="' + el.getAttribute("data-wpc-id") + '"]');
            if (existBar) existBar.parentNode.removeChild(existBar);
        }
        saveEditEx(el, "section", "", { hidden: newHidden });
    }

    /* ── Background popover (overrideId = use this id for save when opening from section+background) ── */
    function openBackgroundPopover(el, overrideId) {
        var bgId = (overrideId != null && overrideId !== "") ? overrideId : null;
        var styleEl = el;
        if (bgId) {
            var target = document.querySelector("[data-wpc-id=\"" + bgId + "\"]");
            if (target) styleEl = target;
        }
        var cs = window.getComputedStyle(styleEl);
        var currentColor = cs.backgroundColor || "";
        var hexColor = rgbToHex(currentColor);
        var bgImgVal = "";
        if (cs.backgroundImage && cs.backgroundImage !== "none") {
            var m = (cs.backgroundImage || "").match(/url\(["']?([^"')]+)["']?\)/);
            if (m) bgImgVal = m[1].trim();
        }
        var bgVideoVal = "";
        var vidEl = el.querySelector(".wpc-bg-video video, .wpc-bg-video iframe");
        if (vidEl) {
            if (vidEl.tagName === "VIDEO") {
                bgVideoVal = vidEl.getAttribute("src") || (vidEl.querySelector("source") && vidEl.querySelector("source").getAttribute("src")) || "";
            } else {
                bgVideoVal = vidEl.getAttribute("src") || "";
            }
        }
        // EC-EDITOR-033: Pre-fill from native hero background video when not editor-injected.
        if (!bgVideoVal) {
            var bgSection = el.tagName === "SECTION" ? el : el.closest("section");
            if (bgSection) {
                var heroVid = resolveHeroVideoEl(bgSection);
                if (heroVid) {
                    var nativeMedia = heroVid._wpcMediaEl || heroVid;
                    if (nativeMedia.tagName === "VIDEO") {
                        bgVideoVal = nativeMedia.getAttribute("src") || "";
                        if (!bgVideoVal) {
                            var srcEl = nativeMedia.querySelector("source");
                            if (srcEl) bgVideoVal = srcEl.getAttribute("src") || "";
                        }
                    } else {
                        bgVideoVal = nativeMedia.getAttribute("src") || "";
                    }
                }
            }
        }
        var heroBgSection = el.tagName === "SECTION" ? el : el.closest("section");
        var hasHeroVideo = !!(heroBgSection && resolveHeroVideoEl(heroBgSection));
        var hasBgMedia = !!(bgImgVal || bgVideoVal || hasHeroVideo);
        var colorBlock =
            '<label>Background Color</label>' +
            '<div class="wpc-bg-color-row">' +
              '<input type="color" class="wpc-bg-picker" value="' + (hexColor || "#ffffff") + '">' +
              '<input type="text" class="wpc-bg-hex" value="' + escAttr(hexColor || "") + '" placeholder="#hex">' +
            '</div>';
        var actionsBlock =
            '<button type="button" class="wpc-bg-remove-btn">Remove Background</button>' +
            '<div class="wpc-popover-actions">' +
              '<button class="wpc-save-btn" style="background:#22c55e;color:#fff;">Save</button>' +
              '<button class="wpc-cancel-btn" style="background:#e2e8f0;color:#334155;">Cancel</button>' +
              '<button class="wpc-reset-btn" style="background:transparent;color:#f87171;text-decoration:underline;">Reset</button>' +
            '</div>';
        var mediaBlock =
            '<label>Background Image (hero / section)</label>' +
            '<input type="url" class="wpc-bg-imgurl" value="' + escAttr(bgImgVal) + '" placeholder="Image URL">' +
            '<div style="margin-bottom:8px;"><button type="button" class="wpc-media-btn" style="width:100%;padding:8px;border:1px dashed #94a3b8;border-radius:6px;background:#f8fafc;cursor:pointer;font-size:12px;color:#475569;">Choose from Media Library</button></div>' +
            '<label>Background Video (YouTube / Vimeo / direct URL)</label>' +
            '<input type="url" class="wpc-bg-videourl" value="' + escAttr(bgVideoVal) + '" placeholder="Video URL">' +
            '<p style="font-size:11px;color:#94a3b8;margin:4px 0 10px;">Overrides image when set. Leave empty for image/color only.</p>';

        popover = document.createElement("div");
        popover.className = "wpc-popover";
        popover.style.width = "320px";
        popover.innerHTML = colorBlock + (hasBgMedia ? mediaBlock : "") + actionsBlock;

        document.body.appendChild(popover);
        positionPopover(el);

        var picker = popover.querySelector(".wpc-bg-picker");
        var hexInput = popover.querySelector(".wpc-bg-hex");
        picker.addEventListener("input", function() { hexInput.value = picker.value; });
        hexInput.addEventListener("input", function() { if (/^#[0-9a-f]{6}$/i.test(hexInput.value)) picker.value = hexInput.value; });

        var mediaBtn = popover.querySelector(".wpc-media-btn");
        if (mediaBtn) {
            mediaBtn.onclick = function() {
                if (typeof wp === "undefined" || !wp.media) { alert("Media Library not available."); return; }
                var savedPop = popover;
                var savedAct = activeEl;
                var frame = wp.media({ title: "Select Background Image", multiple: false, library: { type: "image" } });
                frame.on("select", function() {
                    var att = frame.state().get("selection").first().toJSON();
                    if (!att || !att.url) return;
                    var p = popover || savedPop;
                    if (!p) return;
                    if (!p.parentNode) document.body.appendChild(p);
                    popover = p;
                    if (!activeEl && savedAct) {
                        activeEl = savedAct;
                        savedAct.classList.add("wpc-active");
                    }
                    var urlInp = p.querySelector(".wpc-bg-imgurl");
                    if (urlInp) urlInp.value = att.url;
                });
                frame.open();
            };
        }
        popover.querySelector(".wpc-bg-remove-btn").onclick = function() {
            styleEl.style.backgroundImage = "none";
            styleEl.style.backgroundColor = "";
            var wrap = (el.querySelector(".wpc-bg-video") || styleEl.querySelector(".wpc-bg-video"));
            if (wrap) wrap.parentNode.removeChild(wrap);
            saveEditEx(el, "background", "", { bgType: "remove" }, bgId);
        };
        popover.querySelector(".wpc-save-btn").onclick = function() {
            var imgUrlInp = popover.querySelector(".wpc-bg-imgurl");
            var videoUrlInp = popover.querySelector(".wpc-bg-videourl");
            var imgUrl = imgUrlInp ? imgUrlInp.value.trim() : "";
            var videoUrl = videoUrlInp ? videoUrlInp.value.trim() : "";
            var color = hexInput.value.trim();
            if (videoUrl) {
                styleEl.style.backgroundImage = "none";
                styleEl.style.backgroundColor = "";
                var wrap = (el.querySelector(".wpc-bg-video") || styleEl.querySelector(".wpc-bg-video"));
                if (wrap) wrap.parentNode.removeChild(wrap);
                var isYt = /youtube|youtu\.be/i.test(videoUrl);
                var isVimeo = /vimeo/i.test(videoUrl);
                var embedUrl = videoUrl;
                if (videoUrl.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/)([a-zA-Z0-9_-]+)/)) {
                    embedUrl = "https://www.youtube.com/embed/" + videoUrl.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/)([a-zA-Z0-9_-]+)/)[1] + "?autoplay=1&mute=1&loop=1&controls=0";
                } else if (videoUrl.match(/vimeo\.com\/(\d+)/)) {
                    embedUrl = "https://player.vimeo.com/video/" + videoUrl.match(/vimeo\.com\/(\d+)/)[1] + "?autoplay=1&muted=1&loop=1";
                }
                if (isYt || isVimeo) {
                    var div = document.createElement("div");
                    div.className = "wpc-bg-video";
                    div.style.cssText = "position:absolute;inset:0;z-index:0;overflow:hidden;";
                    var iframe = document.createElement("iframe");
                    iframe.src = embedUrl;
                    iframe.style.cssText = "position:absolute;top:50%;left:50%;width:100vmax;height:100vmax;min-width:100%;min-height:100%;transform:translate(-50%,-50%);object-fit:cover;";
                    iframe.setAttribute("allow", "autoplay;fullscreen");
                    iframe.allowFullscreen = true;
                    div.appendChild(iframe);
                    el.insertBefore(div, el.firstChild);
                } else {
                    var div = document.createElement("div");
                    div.className = "wpc-bg-video";
                    div.style.cssText = "position:absolute;inset:0;z-index:0;";
                    var video = document.createElement("video");
                    video.src = videoUrl;
                    video.autoplay = true;
                    video.muted = true;
                    video.loop = true;
                    video.playsInline = true;
                    video.style.cssText = "width:100%;height:100%;object-fit:cover;";
                    div.appendChild(video);
                    el.insertBefore(div, el.firstChild);
                }
                if (el.style.position !== "relative") el.style.position = "relative";
                saveEditEx(el, "background", videoUrl, { bgType: "video" }, bgId);
            } else if (imgUrl) {
                styleEl.style.backgroundImage = "url(" + imgUrl + ")";
                styleEl.style.backgroundSize = "cover";
                styleEl.style.backgroundPosition = "center";
                var wrap = (el.querySelector(".wpc-bg-video") || styleEl.querySelector(".wpc-bg-video"));
                if (wrap) wrap.parentNode.removeChild(wrap);
                saveEditEx(el, "background", imgUrl, { bgType: "image" }, bgId);
            } else if (color) {
                styleEl.style.backgroundColor = color;
                var wrap = (el.querySelector(".wpc-bg-video") || styleEl.querySelector(".wpc-bg-video"));
                if (wrap) wrap.parentNode.removeChild(wrap);
                saveEditEx(el, "background", color, { bgType: "color" }, bgId);
            } else {
                cleanup();
            }
        };
        popover.querySelector(".wpc-cancel-btn").onclick = function() { cleanup(); };
        popover.querySelector(".wpc-reset-btn").onclick = function() { resetEdit(el, bgId); };
    }

    function rgbToHex(rgb) {
        var m = (rgb || "").match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
        if (!m) return "";
        return "#" + [m[1], m[2], m[3]].map(function(x) { return parseInt(x).toString(16).padStart(2, "0"); }).join("");
    }

    /* ── List editor ── */

    /* EC-EDITOR-064: A Weebly bullet carries its typography per item —
     *   <li><strong><font color="#2a2a2a"><font size="2">…</font></font></strong></li>
     * The editor only ever showed the stripped text, so saving rebuilt each <li>
     * with textContent and the whole list lost its colour and size. wp_kses_post
     * on the PHP side already allows <strong>/<font>, so the markup only had to
     * survive the round trip: keep each item's original HTML next to its text and
     * pour the edited text back into the same wrapper chain. */
    function escHtml(s) {
        var d = document.createElement("div");
        d.textContent = s === null || s === undefined ? "" : String(s);
        return d.innerHTML;
    }

    function wpcReskinListItem(skinHtml, text) {
        if (!skinHtml) return escHtml(text);
        var box = document.createElement("div");
        box.innerHTML = skinHtml;
        if (!box.querySelector("*")) return escHtml(text);
        var walker = document.createTreeWalker(box, NodeFilter.SHOW_TEXT, null, false);
        var nodes = [];
        var n;
        while ((n = walker.nextNode())) nodes.push(n);
        var target = null;
        for (var i = 0; i < nodes.length; i++) {
            if (nodes[i].nodeValue.replace(/[\u200b\ufeff\s]/g, "")) { target = nodes[i]; break; }
        }
        if (!target) {
            var deepest = box.querySelector("*");
            while (deepest.firstElementChild) deepest = deepest.firstElementChild;
            deepest.textContent = text;
            return box.innerHTML;
        }
        target.nodeValue = text;
        for (var j = 0; j < nodes.length; j++) {
            if (nodes[j] !== target) nodes[j].nodeValue = "";
        }
        return box.innerHTML;
    }

    function openListEditor(el) {
        var items = [];
        var lis = el.querySelectorAll(":scope > li");
        lis.forEach(function(li) {
            var html = li.innerHTML.trim();
            items.push({ html: html, text: (li.textContent || "").replace(/[\u200b\ufeff]/g, "").trim() });
        });
        originalValue = el.innerHTML;

        popover = document.createElement("div");
        popover.className = "wpc-popover";
        popover.style.width = "360px";

        function renderList() {
            var html = '<label>List Items</label><div class="wpc-list-items">';
            items.forEach(function(item, i) {
                var plainText = item.text;
                html += '<div class="wpc-list-item-row" data-idx="' + i + '">' +
                    '<button type="button" class="wpc-move-btn" data-dir="up" title="Move up">&uarr;</button>' +
                    '<button type="button" class="wpc-move-btn" data-dir="down" title="Move down">&darr;</button>' +
                    '<input type="text" value="' + escAttr(plainText) + '">' +
                    '<button type="button" class="wpc-remove-item" title="Remove">&times;</button>' +
                '</div>';
            });
            html += '</div>' +
                '<button type="button" class="wpc-add-item-btn">+ Add item</button>' +
                '<div class="wpc-popover-actions">' +
                  '<button class="wpc-save-btn" style="background:#22c55e;color:#fff;">Save</button>' +
                  '<button class="wpc-cancel-btn" style="background:#e2e8f0;color:#334155;">Cancel</button>' +
                  '<button class="wpc-reset-btn" style="background:transparent;color:#f87171;text-decoration:underline;">Reset</button>' +
                '</div>';
            popover.innerHTML = html;
            attachListEvents();
        }

        /* EC-EDITOR-064: carry each item's original wrapper chain across the
         * round trip; row order matches items order because renderList redraws
         * from items every time. */
        function collectItems() {
            var next = [];
            popover.querySelectorAll(".wpc-list-item-row input").forEach(function(inp, i) {
                var prev = items[i] || {};
                next.push({ html: prev.html || "", text: inp.value });
            });
            items = next;
        }

        function attachListEvents() {
            popover.querySelectorAll(".wpc-remove-item").forEach(function(btn) {
                btn.onclick = function() {
                    collectItems();
                    var idx = parseInt(btn.closest(".wpc-list-item-row").getAttribute("data-idx"));
                    items.splice(idx, 1);
                    renderList();
                };
            });
            popover.querySelectorAll(".wpc-move-btn").forEach(function(btn) {
                btn.onclick = function() {
                    collectItems();
                    var idx = parseInt(btn.closest(".wpc-list-item-row").getAttribute("data-idx"));
                    var dir = btn.getAttribute("data-dir");
                    var swap = dir === "up" ? idx - 1 : idx + 1;
                    if (swap < 0 || swap >= items.length) return;
                    var tmp = items[idx]; items[idx] = items[swap]; items[swap] = tmp;
                    renderList();
                };
            });
            popover.querySelector(".wpc-add-item-btn").onclick = function() {
                collectItems();
                /* EC-EDITOR-064: a new bullet borrows the last item's formatting
                 * so it does not read as unstyled next to its siblings. */
                var skin = items.length ? items[items.length - 1].html : "";
                items.push({ html: skin, text: "New item" });
                renderList();
            };
            popover.querySelector(".wpc-save-btn").onclick = function() {
                collectItems();
                var payload = items.map(function(it) {
                    return wpcReskinListItem(it.html, it.text);
                });
                while (el.firstChild) el.removeChild(el.firstChild);
                payload.forEach(function(h) {
                    var li = document.createElement("li");
                    li.innerHTML = h;
                    el.appendChild(li);
                });
                saveEditEx(el, "list", JSON.stringify(payload), {});
            };
            popover.querySelector(".wpc-cancel-btn").onclick = function() { el.innerHTML = originalValue; cleanup(); };
            popover.querySelector(".wpc-reset-btn").onclick = function() { resetEdit(el); };
        }

        document.body.appendChild(popover);
        renderList();
        positionPopover(el);
    }

    /* ── Video popover ── */
    function openVideoPopover(el) {
        var media = el._wpcMediaEl || ((el.tagName === "IFRAME" || el.tagName === "VIDEO") ? el : el.querySelector("iframe, video"));
        // EC-VIDEO-001: Also handle <img> video thumbnails (tagged as data-wpc-editable="video")
        var isVideoThumbnail = !media && el.tagName === "IMG";
        if (!media && !isVideoThumbnail) return;
        var wrapper = el;
        var tag = media ? media.tagName.toLowerCase() : "img";
        var currentSrc = "";
        if (isVideoThumbnail) {
            var card = el.closest("[data-video-url]");
            currentSrc = card ? card.getAttribute("data-video-url") : "";
            if (!currentSrc && el.getAttribute("data-wpc-id") && typeof wpcEditableManifest !== "undefined") {
                var mEntry = wpcEditableManifest.find(function(e) { return e.id === el.getAttribute("data-wpc-id"); });
                if (mEntry && mEntry.defaultValue && /youtube|youtu\.be|vimeo|wistia|loom/i.test(mEntry.defaultValue)) {
                    currentSrc = mEntry.defaultValue;
                }
            }
            if (!currentSrc) {
                var ytMatch = (el.getAttribute("src") || "").match(/img\.youtube\.com\/vi\/([a-zA-Z0-9_-]+)\//);
                if (ytMatch) currentSrc = "https://www.youtube.com/watch?v=" + ytMatch[1];
            }
        } else if (tag === "video") {
            currentSrc = media.getAttribute("src") || "";
            if (!currentSrc) { var s = media.querySelector("source"); if (s) currentSrc = s.getAttribute("src") || ""; }
        } else {
            currentSrc = media.getAttribute("src") || "";
        }
        originalValue = currentSrc;
        var vType = tag === "video" ? "html5" : (/vimeo/i.test(currentSrc) ? "vimeo" : "youtube");

        // Detect existing thumbnail image
        var thumbImg = null;
        var thumbSrc = "";
        if (isVideoThumbnail) {
            thumbImg = el;
            thumbSrc = el.getAttribute("src") || "";
        } else {
            // Look for a sibling/child <img> that serves as the poster/thumbnail
            var searchRoot = el.closest("[data-video-url]") || el.parentElement;
            if (searchRoot) thumbImg = searchRoot.querySelector("img");
            if (thumbImg) thumbSrc = thumbImg.getAttribute("src") || "";
        }
        var originalThumbSrc = thumbSrc;

        popover = document.createElement("div");
        popover.className = "wpc-popover";
        popover.innerHTML =
            '<label>Video URL</label>' +
            '<input type="url" class="wpc-video-url" value="' + escAttr(currentSrc) + '" placeholder="Paste a YouTube, Vimeo, or direct video URL">' +
            '<p style="font-size:11px;color:#94a3b8;margin:0 0 10px;">YouTube watch URLs are auto-converted to embeds</p>' +
            (thumbImg ? (
                '<hr style="border:none;border-top:1px solid #334155;margin:4px 0 10px;">' +
                '<label>Video Thumbnail</label>' +
                '<input type="url" class="wpc-thumb-url" value="' + escAttr(thumbSrc) + '" placeholder="Image URL for thumbnail">' +
                '<div style="margin:6px 0 4px;display:flex;gap:6px;">' +
                  '<button type="button" class="wpc-thumb-media-btn" style="flex:1;padding:7px;border:1px dashed #94a3b8;border-radius:6px;background:#f8fafc;cursor:pointer;font-size:12px;color:#475569;">Choose from Media Library</button>' +
                '</div>' +
                '<div class="wpc-thumb-preview" style="margin:6px 0 10px;max-height:100px;overflow:hidden;border-radius:6px;">' +
                  (thumbSrc ? '<img src="' + escAttr(thumbSrc) + '" style="width:100%;height:80px;object-fit:cover;border-radius:6px;">' : '') +
                '</div>'
            ) : '') +
            '<div class="wpc-popover-actions">' +
              '<button class="wpc-save-btn" style="background:#22c55e;color:#fff;">Save</button>' +
              '<button class="wpc-cancel-btn" style="background:#e2e8f0;color:#334155;">Cancel</button>' +
              '<button class="wpc-reset-btn" style="background:transparent;color:#f87171;text-decoration:underline;">Reset</button>' +
            '</div>';

        document.body.appendChild(popover);
        positionPopover(wrapper);

        // Thumbnail URL live preview
        var thumbUrlInput = popover.querySelector(".wpc-thumb-url");
        if (thumbUrlInput) {
            thumbUrlInput.addEventListener("input", function() {
                var v = thumbUrlInput.value.trim();
                if (v && thumbImg) thumbImg.setAttribute("src", v);
                var prev = popover.querySelector(".wpc-thumb-preview");
                if (prev) prev.innerHTML = v ? '<img src="' + escAttr(v) + '" style="width:100%;height:80px;object-fit:cover;border-radius:6px;">' : '';
            });
        }

        // Thumbnail media library picker
        var thumbMediaBtn = popover.querySelector(".wpc-thumb-media-btn");
        if (thumbMediaBtn) {
            thumbMediaBtn.onclick = function() {
                openVideoThumbnailLibrary(thumbImg, thumbUrlInput, popover);
            };
        }

        popover.querySelector(".wpc-save-btn").onclick = function() {
            var url = popover.querySelector(".wpc-video-url").value.trim();
            var newThumbUrl = thumbUrlInput ? thumbUrlInput.value.trim() : "";

            if (!url && !newThumbUrl) { cleanup(); return; }
            var embedUrl = url;
            var ytMatch = url.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/)([a-zA-Z0-9_-]+)/);
            if (ytMatch) embedUrl = "https://www.youtube.com/embed/" + ytMatch[1];
            var vmMatch = url.match(/vimeo\.com\/(\d+)/);
            if (vmMatch) embedUrl = "https://player.vimeo.com/video/" + vmMatch[1];

            if (isVideoThumbnail) {
                var card = el.closest("[data-video-url]") || el.closest('[class*="cursor-pointer"]') || el.parentElement;
                if (card && url) card.setAttribute("data-video-url", url);
                if (newThumbUrl && thumbImg) thumbImg.setAttribute("src", newThumbUrl);
            } else if (tag === "video") {
                if (url) {
                    media.setAttribute("src", embedUrl);
                    var src = media.querySelector("source");
                    if (src) src.setAttribute("src", embedUrl);
                }
                if (newThumbUrl && thumbImg) thumbImg.setAttribute("src", newThumbUrl);
            } else {
                if (url) media.setAttribute("src", embedUrl);
                if (newThumbUrl && thumbImg) thumbImg.setAttribute("src", newThumbUrl);
            }

            var extra = { videoType: vType };
            if (newThumbUrl && newThumbUrl !== originalThumbSrc) {
                extra.thumbnailUrl = newThumbUrl;
            }
            saveEditEx(wrapper, "video", url || currentSrc, extra);
        };
        onCancel = function() { if (thumbImg && originalThumbSrc) thumbImg.setAttribute("src", originalThumbSrc); };
        popover.querySelector(".wpc-cancel-btn").onclick = function() { onCancel(); onCancel = null; cleanup(); };
        popover.querySelector(".wpc-reset-btn").onclick = function() { onCancel = null; resetEdit(wrapper); };
    }

    function openVideoThumbnailLibrary(thumbImg, thumbUrlInput, savedPopover) {
        if (typeof wp === "undefined" || !wp.media) {
            alert("Media Library not available. Please enter the URL manually.");
            return;
        }
        var savedActive = activeEl;
        var frame = wp.media({ title: "Select Video Thumbnail", multiple: false, library: { type: "image" } });
        frame.on("select", function() {
            var attachment = frame.state().get("selection").first().toJSON();
            if (!attachment || !attachment.url) return;
            var p = popover || savedPopover;
            if (!p) return;
            if (!p.parentNode) document.body.appendChild(p);
            popover = p;
            if (!activeEl && savedActive) {
                activeEl = savedActive;
                savedActive.classList.add("wpc-active");
            }
            if (thumbUrlInput) {
                thumbUrlInput.value = attachment.url;
                thumbUrlInput.dispatchEvent(new Event("input"));
            }
            if (thumbImg) thumbImg.setAttribute("src", attachment.url);
        });
        frame.open();
    }

    /* ── Upgrade prompt for Starter users ── */
    function showUpgradePrompt(el, type) {
        var label = badgeLabels[type] || type;
        popover = document.createElement("div");
        popover.className = "wpc-popover wpc-upgrade-prompt";
        popover.innerHTML =
            '<div style="text-align:center;padding:8px 0 4px;">' +
              '<div style="font-size:28px;margin-bottom:6px;">&#128274;</div>' +
              '<div style="font-size:14px;font-weight:700;color:#1e293b;margin-bottom:6px;">WPConvert Edit PRO</div>' +
              '<p style="font-size:13px;color:#64748b;margin:0 0 14px;line-height:1.5;">' + escAttr(label) + ' editing is a PRO feature.<br>Upgrade to PRO, Agency, or purchase<br>PAYG credits, then re-convert your site to unlock.</p>' +
              '<div class="wpc-popover-actions" style="justify-content:center;">' +
                '<a href="https://app.wpconvert.ai/dashboard/billing" target="_blank" rel="noopener noreferrer" class="wpc-upgrade-link" style="flex:none;display:inline-block;background:#3b82f6;color:#fff;padding:9px 20px;border-radius:6px;font-size:12px;font-weight:600;text-decoration:none;">Upgrade Now</a>' +
                '<button class="wpc-cancel-btn" style="flex:none;background:#e2e8f0;color:#334155;padding:9px 16px;">Close</button>' +
              '</div>' +
            '</div>';
        document.body.appendChild(popover);
        positionPopover(el);
        popover.querySelector(".wpc-cancel-btn").onclick = function() { cleanup(); };
    }

    /* ── Cache-busting helper (primes a fresh server response) ── */
    function bustCache() {
        var baseUrl = window.location.href
            .replace(/([?&])_wpc_t=\d+/, "$1")
            .replace(/[?&]$/, "");
        var sep = baseUrl.indexOf("?") !== -1 ? "&" : "?";
        fetch(baseUrl + sep + "_wpc_t=" + Date.now(), { cache: "no-store", credentials: "same-origin" }).catch(function(){});
    }

    /* ── Extended AJAX save (supports extra fields) ── */
    function buildSaveFormData(id, type, value, extra) {
        var fd = new FormData();
        fd.append("action", "wpconvert_save_edit");
        fd.append("nonce", nonce);
        fd.append("wpc_id", id);
        fd.append("type", type);
        fd.append("value", value || "");
        fd.append("href", (extra && extra.href) || "");
        fd.append("alt", (extra && extra.alt) || "");
        fd.append("target", (extra && extra.target) || "");
        if (extra && extra.hidden !== undefined) fd.append("hidden", extra.hidden ? "1" : "");
        if (extra && extra.bgType) fd.append("bgType", extra.bgType);
        if (extra && extra.videoType) fd.append("videoType", extra.videoType);
        if (extra && extra.thumbnailUrl) fd.append("thumbnailUrl", extra.thumbnailUrl);
        if (extra && extra.bgColor !== undefined) fd.append("bgColor", extra.bgColor);
        if (extra && extra.textColor !== undefined) fd.append("textColor", extra.textColor);
        return fd;
    }

    function postSaveFormData(fd) {
        return fetch(ajax, { method: "POST", credentials: "same-origin", body: fd }).then(function(r) { return r.json(); });
    }

    function saveEditEx(el, type, value, extra, overrideId) {
        var id = (overrideId != null && overrideId !== "") ? overrideId : el.getAttribute("data-wpc-id");
        /* EC-EDITOR-038: data-wpc-orig is session bookkeeping. Every save path
           funnels through here, so this is the one place it has to be stripped
           before the markup is persisted. */
        if (typeof value === "string" && value.indexOf("data-wpc-orig") !== -1) {
            value = value.replace(/\s*data-wpc-orig="1"/g, "");
        }
        if (type === "heading" && typeof value === "string") {
            value = wpcNormalizeHeadingHtml(value);
        }
        var fd = buildSaveFormData(id, type, value, extra || {});
        cleanup();
        postSaveFormData(fd)
            .then(function(data) {
                if (data.success) {
                    el.classList.add("wpc-flash-success");
                    setTimeout(function() { el.classList.remove("wpc-flash-success"); }, 700);
                    bustCache();
                } else {
                    alert("Save failed: " + (data.data || "Unknown error"));
                }
            })
            .catch(function(err) { alert("Save error: " + err.message); });
    }

    function positionPopover(el) {
        if (!popover) return;
        var pw = popover.offsetWidth || 320;
        var ph = popover.offsetHeight || 260;
        var top, left;
        if (lastClickX || lastClickY) {
            top = lastClickY + 12;
            left = lastClickX - Math.round(pw / 2);
        } else {
            var rect = el.getBoundingClientRect();
            top = rect.bottom + 8;
            left = rect.left;
        }
        if (top + ph > window.innerHeight) top = (lastClickY || window.innerHeight / 2) - ph - 12;
        if (top < 10) top = 10;
        if (left + pw > window.innerWidth) left = window.innerWidth - pw - 10;
        if (left < 10) left = 10;
        popover.style.top = top + "px";
        popover.style.left = left + "px";
    }

    /* ── AJAX save (delegates to saveEditEx) ── */
    function saveEdit(el, type, value, href, alt) {
        saveEditEx(el, type, value, { href: href || "", alt: alt || "" });
    }

    /* ── AJAX reset ── */
    function resetEdit(el, overrideId) {
        var id = (overrideId != null && overrideId !== "") ? overrideId : el.getAttribute("data-wpc-id");
        if (!id) { alert("Cannot reset: element has no ID"); cleanup(); return; }

        postResetWpcId(id)
            .then(function(data) {
                if (!data || !data.success) {
                    alert("Reset failed: " + ((data && data.data) || "Unknown error"));
                    cleanup();
                    return;
                }
                cleanup();
                reloadAfterReset();
            })
            .catch(function(err) { alert("Reset error: " + err.message); cleanup(); });
    }

    /* ── EC-EDITOR-037: Unsaved-change guards ── */
    function ensurePopoverSnapshot() {
        if (!popover || popover._wpcFieldSnap) return;
        popover._wpcFieldSnap = {};
        popover.querySelectorAll("input, textarea, select").forEach(function(f, i) {
            if (f.type === "file") return;
            popover._wpcFieldSnap[i] = f.value;
            f._wpcSnapIdx = i;
        });
    }

    function popoverIsDirty() {
        if (!popover) return false;
        ensurePopoverSnapshot();
        var snap = popover._wpcFieldSnap || {};
        var dirty = false;
        popover.querySelectorAll("input, textarea, select").forEach(function(f) {
            if (f.type === "file") return;
            if (f._wpcSnapIdx !== undefined && f.value !== snap[f._wpcSnapIdx]) dirty = true;
        });
        return dirty;
    }

    function hasUnsavedWork() {
        if (activeEl && activeEl.getAttribute("contenteditable") === "true") {
            return activeEl.innerHTML !== originalValue;
        }
        return popoverIsDirty();
    }

    function revertActiveEdit() {
        if (onCancel) { onCancel(); onCancel = null; }
        if (activeEl && activeEl.getAttribute("contenteditable") === "true") {
            activeEl.innerHTML = originalValue;
        }
        cleanup();
    }

    function saveActiveEditAsync() {
        return new Promise(function(resolve) {
            if (activeEl && activeEl.getAttribute("contenteditable") === "true") {
                var type = activeEl.getAttribute("data-wpc-editable") || "text";
                var el = activeEl;
                var id = el.getAttribute("data-wpc-id");
                if (!id) { cleanup(); resolve(false); return; }
                var fd = buildSaveFormData(id, type, el.innerHTML, {});
                cleanup();
                postSaveFormData(fd)
                    .then(function(data) {
                        if (data && data.success) bustCache();
                        else alert("Save failed: " + ((data && data.data) || "Unknown error"));
                        resolve(!!(data && data.success));
                    })
                    .catch(function(err) { alert("Save error: " + err.message); resolve(false); });
                return;
            }
            if (popover) {
                var saveBtn = popover.querySelector(".wpc-save-btn");
                if (saveBtn) { saveBtn.click(); resolve(true); return; }
            }
            cleanup();
            resolve(true);
        });
    }

    function promptUnsavedChanges(onSettled) {
        if (!hasUnsavedWork()) {
            if (onSettled) onSettled();
            return;
        }
        var save = window.confirm(
            "Unsaved changes — Save or Cancel?\n\nClick OK to save, or Cancel to discard."
        );
        if (save) {
            saveActiveEditAsync().then(function() { if (onSettled) onSettled(); });
        } else {
            revertActiveEdit();
            if (onSettled) onSettled();
        }
    }

    function bindExitGuard() {
        var exitLink = document.querySelector("#wp-admin-bar-wpconvert-edit > a.ab-item");
        if (!exitLink || exitLink._wpcExitBound) return;
        exitLink._wpcExitBound = true;
        exitLink.addEventListener("click", function(e) {
            if (!hasUnsavedWork()) return;
            e.preventDefault();
            var href = exitLink.href;
            promptUnsavedChanges(function() { window.location.href = href; });
        });
    }

    window.addEventListener("beforeunload", function(e) {
        if (!hasUnsavedWork()) return;
        e.preventDefault();
        e.returnValue = "";
    });

    /* ── Cleanup ── */
    function cleanup() {
        onCancel = null;
        if (activeEl) {
            /* EC-EDITOR-031: detach the paste sanitizer so handlers don't stack
               across edit sessions. */
            if (activeEl._wpcPasteHandler) {
                activeEl.removeEventListener("paste", activeEl._wpcPasteHandler);
                activeEl._wpcPasteHandler = null;
            }
            if (activeEl._wpcInlineKeyHandler) {
                activeEl.removeEventListener("keydown", activeEl._wpcInlineKeyHandler);
                activeEl._wpcInlineKeyHandler = null;
            }
            if (activeEl._wpcInlineInputHandler) {
                activeEl.removeEventListener("input", activeEl._wpcInlineInputHandler);
                activeEl._wpcInlineInputHandler = null;
            }
            activeEl.classList.remove("wpc-edit-heading");
            activeEl.removeAttribute("contenteditable");
            activeEl.classList.remove("wpc-active");
            /* EC-EDITOR-038: clear the session markers so the next edit of this
               element starts from what is on the page NOW — otherwise text the
               user pasted last session would be treated as original. */
            try {
                var origNodes = activeEl.querySelectorAll("[data-wpc-orig]");
                for (var ci = 0; ci < origNodes.length; ci++) {
                    origNodes[ci].removeAttribute("data-wpc-orig");
                }
            } catch (eClean) {}
            activeEl = null;
        }
        if (toolbar && toolbar.parentNode) {
            toolbar.parentNode.removeChild(toolbar);
            toolbar = null;
        }
        if (popover && popover.parentNode) {
            popover.parentNode.removeChild(popover);
            popover = null;
        }
        hideBadge();
    }

    function escAttr(s) {
        return String(s).replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
    }

    /* ── Close on Escape, Cmd+Enter save, or outside click ── */
    document.addEventListener("keydown", function(e) {
        if (e.key === "Escape") {
            if (onCancel) { onCancel(); onCancel = null; }
            else if (activeEl && activeEl.getAttribute("contenteditable") === "true") {
                activeEl.innerHTML = originalValue;
            }
            cleanup();
        }
        if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
            e.preventDefault();
            if (activeEl && activeEl.getAttribute("contenteditable") === "true") {
                var type = activeEl.getAttribute("data-wpc-editable");
                var html = activeEl.innerHTML;
                if (type === "heading") html = wpcNormalizeHeadingHtml(html);
                saveEdit(activeEl, type || "text", html);
            } else if (popover) {
                var saveBtn = popover.querySelector(".wpc-save-btn");
                if (saveBtn) saveBtn.click();
            }
        }
    });
    document.addEventListener("click", function(e) {
        if (!activeEl && !popover) return;
        if (toolbar && toolbar.contains(e.target)) return;
        if (popover && popover.contains(e.target)) return;
        if (activeEl && activeEl.contains(e.target)) return;
        if (document.querySelector(".media-modal")) return;
        if (!hasUnsavedWork()) {
            cleanup();
            return;
        }
        e.preventDefault();
        e.stopPropagation();
        promptUnsavedChanges(function() {});
    }, true);

    /* ── Init on DOM ready ── */
    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", init);
    } else {
        init();
    }
})();
WPCJS;
}

