function wpconvert_editor_activation_notice() {
    if ( ! current_user_can( 'manage_options' ) ) {
        return;
    }
    $dismissed = get_option( 'wpconvert_editor_notice_dismissed', false );
    if ( $dismissed ) {
        return;
    }
    if ( isset( $_GET['wpconvert-dismiss-notice'] ) && $_GET['wpconvert-dismiss-notice'] === '1' ) {
        update_option( 'wpconvert_editor_notice_dismissed', true, false );
        return;
    }
    $editor_page = wpconvert_editor_admin_guide_url();
    $dismiss_url = esc_url( add_query_arg( 'wpconvert-dismiss-notice', '1' ) );
    $front_edit  = esc_url( add_query_arg( 'wpc_edit', '1', home_url( '/' ) ) );
    $is_pro      = wpconvert_editor_is_pro();
    $labels      = wpconvert_editor_labels();
    $has_cpt     = wpconvert_editor_has_cpt_plugin_bundle() && ! empty( wpconvert_editor_get_cpt_candidates_summary() );
    $has_blog    = wpconvert_editor_has_native_blog();
    ?>
    <div class="notice notice-info" style="padding:12px 16px;border-left-color:#2563eb">
        <p style="font-size:14px;margin:0 0 6px">
            <strong>&#9998; <?php echo esc_html( $labels['activation_ready'] ); ?></strong>
            Edit existing content on the front end — headings, images, buttons, and more.
        </p>
        <p style="font-size:13px;color:#555;margin:0 0 8px;line-height:1.6">
            The editor does <em>not</em> create new pages by itself.
            <?php if ( $is_pro ) : ?>
                To add a new designed page, use <strong>Add a page</strong> in your WPConvert dashboard.
            <?php endif; ?>
            <?php if ( $has_cpt ) : ?>
                <?php echo $is_pro ? ' ' : ''; ?>To manage repeating lists, install <strong>wpconvert-cpt.zip</strong> from your theme's <code>plugins/</code> folder.
            <?php endif; ?>
            <?php if ( $has_blog ) : ?>
                <?php echo ( $is_pro || $has_cpt ) ? ' ' : ''; ?>New blog articles: <strong>Posts &rarr; Add New</strong>.
            <?php endif; ?>
            <a href="<?php echo esc_url( $editor_page ); ?>">See the full guide &rarr;</a>
        </p>
        <p style="margin:0">
            <a href="<?php echo $front_edit; ?>" class="button button-primary button-small">Start Editing (Home Section)</a>
            <a href="<?php echo esc_url( $editor_page ); ?>" class="button button-small" style="margin-left:4px"><?php echo esc_html( $labels['activation_guide'] ); ?></a>
            <a href="<?php echo $dismiss_url; ?>" style="margin-left:12px;font-size:12px;color:#888;text-decoration:none">Dismiss</a>
        </p>
    </div>
    <?php
}
add_action( 'admin_notices', 'wpconvert_editor_activation_notice' );
